// Readings derived from the cockpit: pace now against your usual pace (or,
// until 3 past days are kept, this session's own average), the five-hour
// window as a fuel gauge (used, where the trend ends at the reset, how much of
// the window has passed), and the threshold level of each gauge. Pure.

import { dayPace, HOUR, median, MINUTE, nowRate, paceAt, paceCoverageMs } from './metrics'
import { limitsAt, type Cockpit, type Window } from './model'

/** Colour only on thresholds: `none` draws in the theme's own text colour. */
export type Level = 'none' | 'ok' | 'warn' | 'bad'

/** Below 10 minutes of data the pace needle is grey and only the number shows. */
export const PACE_MIN_DATA_MS = 10 * MINUTE

/** The dial reads 0 to 2× your usual pace: usual straight up, amber from 1.5×, red from 1.8×. */
export const DIAL_MAX_RATIO = 2
export const PACE_WARN_RATIO = 1.5
export const PACE_BAD_RATIO = 1.8

/** A day as the store rolls it up: what `dayPace` takes. */
export type DayTotals = { day: string; tokens: number; activeMin: number }

/** Where "usual" comes from: the median of your last days (3 at least), or this session's own average. */
export type Usual = { perHour: number; basis: 'days' | 'session'; n: number }

/**
 * Your usual pace in tokens per active hour: the median day of the last 14
 * (3 days or more), else this session's own average once it has 10 active
 * minutes, else unknown. `n` is how many days, or how many active minutes.
 */
export function usualOf(c: Cockpit, days: readonly DayTotals[], today: string): Usual | undefined {
  const past = days.filter(d => d.day < today && d.activeMin > 0 && d.tokens > 0).slice(-14)
  if (past.length >= 3) return { perHour: median(past.map(d => dayPace(d.tokens, d.activeMin))) ?? 0, basis: 'days', n: past.length }
  const activeMin = c.activeMs / MINUTE
  if (activeMin >= 10 && c.tokens > 0) return { perHour: dayPace(c.tokens, activeMin), basis: 'session', n: Math.floor(activeMin) }
  return undefined
}

/** Your usual pace's figure alone (see `usualOf`). */
export function usualPace(c: Cockpit, days: readonly DayTotals[], today: string): number | undefined {
  return usualOf(c, days, today)?.perHour
}

export type Eta =
  | { kind: 'empties'; at: number }
  | { kind: 'holds'; resetsAt: number }
  | { kind: 'flat' }

export const FIVE_HOUR_MS = 5 * 60 * MINUTE
export const SEVEN_DAY_MS = 7 * 24 * 60 * MINUTE
/** The readings a five-hour forecast fits a line through. */
export const FIT_SPAN_MS = 90 * MINUTE
const FIT_MIN_READINGS = 3

/** A reading whose window reset has come: that window is over, whatever it said. */
export function isReset(w: Window, now: number): boolean {
  return w.resetsAt !== undefined && w.resetsAt <= now
}

/** Points per millisecond, by least squares through the readings (or undefined with no spread in time). */
function slope(points: readonly [number, number][]): number | undefined {
  const n = points.length
  const mx = points.reduce((a, [x]) => a + x, 0) / n
  const my = points.reduce((a, [, y]) => a + y, 0) / n
  const sxx = points.reduce((a, [x]) => a + (x - mx) ** 2, 0)
  const sxy = points.reduce((a, [x, y]) => a + (x - mx) * (y - my), 0)
  return sxx > 0 ? sxy / sxx : undefined
}

export type Forecast = {
  /** Points per millisecond. */
  rate: number
  /** `fit`: a least-squares line through the last 90 minutes of readings; `average`: the window's use so far over its time so far. */
  how: 'fit' | 'average'
  /** The percent the window reaches at its reset at this rate (past 100 when it runs out first). */
  atReset?: number
  /** When it reaches 100%, if before its reset. */
  emptiesAt?: number
}

/**
 * Where a plan window is heading, from its own readings only. The five-hour
 * window fits a least-squares line through the readings of the last 90
 * minutes (3 at least, 10 minutes apart at least); without that, and for the
 * seven-day window always, the rate is what it used over the time it has
 * been open (its reset less its length), once 10 minutes have passed. A
 * window that has reset has no forecast.
 */
export function forecast(w: Window | undefined, lengthMs: number, readAt: number, samples: readonly [number, number][] | undefined): Forecast | undefined {
  if (!w || isReset(w, readAt)) return undefined
  let rate: number | undefined
  let how: Forecast['how'] = 'fit'
  if (samples) {
    const points = samples.filter(([t]) => t > readAt - FIT_SPAN_MS && t <= readAt)
    const first = points[0]
    const last = points.at(-1)
    if (first && last && points.length >= FIT_MIN_READINGS && last[0] - first[0] >= PACE_MIN_DATA_MS) rate = slope(points)
  }
  if (rate === undefined && w.resetsAt !== undefined) {
    const open = readAt - (w.resetsAt - lengthMs)
    if (open >= PACE_MIN_DATA_MS && open <= lengthMs) {
      rate = w.pct / open
      how = 'average'
    }
  }
  if (rate === undefined) return undefined
  rate = Math.max(0, rate)
  const out: Forecast = { rate, how }
  if (w.resetsAt !== undefined) out.atReset = w.pct + rate * (w.resetsAt - readAt)
  if (rate > 0 && w.pct < 100) {
    const at = readAt + (100 - w.pct) / rate
    if (w.resetsAt === undefined || at < w.resetsAt) out.emptiesAt = at
  }
  return out
}

/** The five-hour window's forecast, from the cockpit's readings. */
export function fiveHourForecast(c: Cockpit): Forecast | undefined {
  const r = c.reading
  return r ? forecast(r.fiveHour, FIVE_HOUR_MS, r.at, c.fiveSamples) : undefined
}

/** The seven-day window's forecast: its average so far (a 90-minute slope would read a working hour as the week). */
export function sevenDayForecast(c: Cockpit): Forecast | undefined {
  const r = c.reading
  return r ? forecast(r.sevenDay, SEVEN_DAY_MS, r.at, undefined) : undefined
}

/** When the five-hour window empties at the rate its readings show, or that it lasts to its reset. */
export function fiveHourEta(c: Cockpit, now: number): Eta | undefined {
  const w = c.reading?.fiveHour
  if (!w || isReset(w, now)) return undefined
  const f = fiveHourForecast(c)
  if (!f) return undefined
  if (f.rate <= 0.01 / MINUTE) return { kind: 'flat' }
  if (f.emptiesAt !== undefined) return { kind: 'empties', at: f.emptiesAt }
  return w.resetsAt !== undefined ? { kind: 'holds', resetsAt: w.resetsAt } : { kind: 'flat' }
}

/** Under this long to its reset, a window the forecast says will last raises no caution. */
export const CALM_BEFORE_RESET_MS = 30 * MINUTE

/** Whether a window that lasts until its reset at this rate resets soon enough that a caution would be noise. */
export function lastsToReset(w: Window, f: Forecast | undefined, now: number): boolean {
  return w.resetsAt !== undefined && w.resetsAt - now < CALM_BEFORE_RESET_MS && f?.atReset !== undefined && f.atReset < 100
}

export type PaceReading = {
  /** New tokens an hour now: each response weighed by how recent it is, halving every 5 minutes. */
  perHour: number
  /** New tokens over the last 60 minutes. */
  hourSum: number
  hasData: boolean
  usual?: number
  /** Where the usual comes from: your last days, or this session's own average (until 3 days are kept). */
  usualBasis?: Usual['basis']
  /** The needle, 0 to 1 across the dial; absent without a usual pace. */
  needle?: number
  /** Now against usual. */
  ratio?: number
  /** The last hour's sum against usual: a slower reading, which health's pace part takes. */
  hourRatio?: number
  eta?: Eta
  level: Level
  /** With no turn running, how long since the last one ended (or since quackpit began watching). */
  idleMs?: number
}

export function paceReading(c: Cockpit, now: number, days: readonly DayTotals[], today: string): PaceReading {
  const perHour = nowRate(c.recent, now)
  const hourSum = paceAt(c.recent, now)
  const hasData = paceCoverageMs(c.startedAt, now) >= PACE_MIN_DATA_MS
  const usual = usualOf(c, days, today)
  const eta = fiveHourEta(c, now)
  const ratio = hasData && usual !== undefined && usual.perHour > 0 ? perHour / usual.perHour : undefined
  const hourRatio = hasData && usual !== undefined && usual.perHour > 0 ? hourSum / usual.perHour : undefined
  let level: Level = 'none'
  if (ratio !== undefined && ratio >= PACE_BAD_RATIO) level = 'bad'
  else if (ratio !== undefined && ratio >= PACE_WARN_RATIO) level = 'warn'
  if (eta?.kind === 'empties' && level === 'none') level = 'warn'
  const lastEnd = c.history.at(-1)?.endedAt ?? c.startedAt
  return {
    perHour,
    hourSum,
    hasData,
    level,
    ...(usual !== undefined ? { usual: usual.perHour, usualBasis: usual.basis } : {}),
    ...(ratio !== undefined ? { ratio, needle: Math.min(1, ratio / DIAL_MAX_RATIO) } : {}),
    ...(hourRatio !== undefined ? { hourRatio } : {}),
    ...(eta ? { eta } : {}),
    ...(c.turn ? {} : { idleMs: Math.max(0, now - lastEnd) }),
  }
}

/** Readings older than this are stale: the fuel gauge's needle goes grey. */
export const STALE_MS = 15 * MINUTE
/** A run-out this near is red: there is little left to do about it. */
export const RUNS_OUT_SOON_MS = 30 * MINUTE

/**
 * The five-hour window as a fuel gauge, for the whole account (other
 * sessions, other machines and claude.ai draw on it too): how much is used,
 * where the trend ends at the reset (the 90-minute fit, or the window's
 * average so far), how much of the window has passed, and when it runs out if
 * that comes first. All of it as of the readings' own time: they come only
 * with this session's responses, so while it is idle they go stale, and
 * `asOf` says since when.
 */
export type FuelGauge = {
  pct: number
  resetsAt?: number
  /** How much of the window has passed, 0 to 1: the dial's tick. */
  elapsed?: number
  /** The percent the window reaches at its reset at this trend (past 100 when it runs out first): where the dial's grey arc ends. */
  atReset?: number
  /** Points an hour: how fast the window has been filling. */
  rate?: number
  how?: Forecast['how']
  /** When it reaches 100%, if before its reset. */
  emptiesAt?: number
  isReset: boolean
  isUsedUp: boolean
  asOf: number
  isStale: boolean
  level: Level
}

export function fuelGauge(c: Cockpit, now: number): FuelGauge | undefined {
  const r = c.reading
  const w = r?.fiveHour
  if (!r || !w) return undefined
  const asOf = limitsAt(c) ?? r.at
  const base = { pct: w.pct, ...(w.resetsAt !== undefined ? { resetsAt: w.resetsAt } : {}), asOf, isStale: now - asOf > STALE_MS }
  if (isReset(w, now)) return { ...base, isReset: true, isUsedUp: false, level: 'none' }
  const isUsedUp = w.pct >= 100
  const f = fiveHourForecast(c)
  const elapsed = w.resetsAt !== undefined ? Math.max(0, Math.min(1, 1 - (w.resetsAt - now) / FIVE_HOUR_MS)) : undefined
  const runsOutSoon = f?.emptiesAt !== undefined && f.emptiesAt - now < RUNS_OUT_SOON_MS
  const level: Level = isUsedUp || w.pct >= 90 || runsOutSoon ? 'bad' : w.pct >= 80 || f?.emptiesAt !== undefined ? 'warn' : 'none'
  return {
    ...base,
    isReset: false,
    isUsedUp,
    ...(elapsed !== undefined ? { elapsed } : {}),
    ...(f?.atReset !== undefined ? { atReset: f.atReset } : {}),
    ...(f ? { rate: f.rate * HOUR, how: f.how } : {}),
    ...(f?.emptiesAt !== undefined && !isUsedUp ? { emptiesAt: f.emptiesAt } : {}),
    level,
  }
}

export function contextLevel(pct: number | undefined): Level {
  if (pct === undefined) return 'none'
  if (pct >= 90) return 'bad'
  if (pct >= 70) return 'warn'
  return 'none'
}

export function fiveHourLevel(w: Window | undefined, now?: number): Level {
  if (!w || (now !== undefined && isReset(w, now))) return 'none'
  if (w.pct >= 90) return 'bad'
  if (w.pct >= 80) return 'warn'
  return 'none'
}

export function sevenDayLevel(w: Window | undefined, now?: number): Level {
  if (!w || (now !== undefined && isReset(w, now))) return 'none'
  if (w.pct >= 90) return 'bad'
  if (w.pct >= 75) return 'warn'
  return 'none'
}

/**
 * The cost of the turn running now: the ledger's growth since the turn began,
 * once a reading shows any. The ledger is read as the turn starts and pushed
 * again only when a plan window moves a point or the turn ends, so until then
 * the growth reads 0, which is no figure: every response costs something.
 */
export function liveTurnUsd(c: Cockpit): number | undefined {
  const start = c.turn?.costAtStart
  const now = c.reading?.costUsd
  return start !== undefined && now !== undefined && now > start ? now - start : undefined
}

/** The worse of two levels. */
export function worse(a: Level, b: Level): Level {
  const rank: Record<Level, number> = { none: 0, ok: 1, warn: 2, bad: 3 }
  return rank[a] >= rank[b] ? a : b
}

files.src/duck.ts:
// The duck is quackpit's Master Caution. It stays still with its head down
// until one of four things needs attention:
//   - a failed check (the latest run of a test, typecheck, lint or build),
//   - the five-hour window at 80% or more (unless it resets within 30 minutes
//     and its forecast says it lasts until then, or its reset has passed),
//   - the context within 10% of the point where Claude Code compacts it by
//     itself (at 90% of the window while auto-compact is off),
//   - a turn that cost over 3x the session's median turn.
// Then it raises its head and its cell says "Quack:". Pressing it
// acknowledges, as a pilot presses the caution light; the gauge stays lit
// until the cause clears. Only a failed check and the five-hour window at
// 90% may raise an OS notification, at most 3 a day. Pure.

import type { CheckKind } from './checks'
import { fiveHourForecast, isReset, lastsToReset } from './derive'
import { formatPercent } from './format'
import { t, type Locale } from './i18n'
import { formatTokens } from './format'
import { contextNow, contextShare, type Cockpit } from './model'
import { displayWidth, fit } from './text'

export type CautionKind = 'check' | 'five' | 'context' | 'runaway'

export type Caution = {
  /** Stable while the cause lasts; a new cause gets a new key. */
  key: string
  kind: CautionKind
  level: 'warn' | 'bad'
  /** Worth an OS notification (a failed check, five_hour at 90%+). */
  isNotify: boolean
  /** When its cause happened: the check's end, the turn's end, the latest reading for the gauges. */
  at: number
  checkKind?: CheckKind
  pct?: number
  /** Tokens left before the auto-compact point, when auto-compact is on. */
  left?: number
  turn?: number
  factor?: number
}

export const FIVE_CAUTION_PCT = 80
export const FIVE_NOTIFY_PCT = 90
/** Of the auto-compact point while auto-compact is on, else of the window. */
export const CONTEXT_CAUTION_PCT = 90
export const NOTIFY_PER_DAY = 3

export function cautionsOf(c: Cockpit, now: number = c.lastAt): Caution[] {
  const out: Caution[] = []
  // Each kind of check whose latest run failed: a chain counts for every check it ran, so a
  // later pass of a kind clears its failure wherever that pass ran (decision 98).
  for (const failure of c.failures) {
    out.push({
      key: `check:${failure.kind}:${failure.at}`,
      kind: 'check',
      level: 'bad',
      isNotify: true,
      at: failure.at,
      checkKind: failure.kind,
    })
  }
  const five = c.reading?.fiveHour
  // A window that has reset is over; one that resets within 30 minutes and lasts until then needs no one.
  if (five && five.pct >= FIVE_CAUTION_PCT && !isReset(five, now) && !lastsToReset(five, fiveHourForecast(c), now)) {
    const isHigh = five.pct >= FIVE_NOTIFY_PCT
    out.push({
      key: `five:${isHigh ? FIVE_NOTIFY_PCT : FIVE_CAUTION_PCT}:${five.resetsAt ?? 0}`,
      kind: 'five',
      level: isHigh ? 'bad' : 'warn',
      isNotify: isHigh,
      at: c.reading?.at ?? 0,
      pct: five.pct,
    })
  }
  const fill = contextNow(c)
  const share = contextShare(fill)
  if (share !== undefined && share >= CONTEXT_CAUTION_PCT) {
    const left = fill.autoCompact !== undefined && fill.tokens !== undefined ? Math.max(0, fill.autoCompact - fill.tokens) : undefined
    out.push({ key: `ctx:${c.compactions}`, kind: 'context', level: 'bad', isNotify: false, at: c.lastAt, ...(fill.pct !== undefined ? { pct: fill.pct } : {}), ...(left !== undefined ? { left } : {}) })
  }
  const last = c.history.at(-1)
  if (last?.runaway && !c.turn) {
    out.push({
      key: `runaway:${last.n}`,
      kind: 'runaway',
      level: 'warn',
      isNotify: false,
      at: last.endedAt,
      turn: last.n,
      ...(last.factor !== undefined ? { factor: last.factor } : {}),
    })
  }
  // Worst first, then by kind, then the newest check. Kind before time, because the
  // gauges' cautions carry the latest reading's time: ordered by time, the one the
  // duck names would change with every reading.
  const rank = { bad: 1, warn: 0 }
  const order: Record<CautionKind, number> = { check: 0, five: 1, context: 2, runaway: 3 }
  return out.sort((a, b) => rank[b.level] - rank[a.level] || order[a.kind] - order[b.kind] || b.at - a.at)
}

export type DuckState = {
  pose: 'idle' | 'alert'
  /** The caution the cell names: the worst one not yet acknowledged. */
  caution?: Caution
  /** How many cautions are live, acknowledged or not. */
  live: number
}

export function duckState(c: Cockpit, cautions: readonly Caution[] = cautionsOf(c)): DuckState {
  const open = cautions.filter(k => !c.ack.includes(k.key))
  const first = open[0]
  return first ? { pose: 'alert', caution: first, live: cautions.length } : { pose: 'idle', live: cautions.length }
}

/** Cautions not yet announced: each gets one toast (and maybe a notification). */
export function freshCautions(c: Cockpit, cautions: readonly Caution[] = cautionsOf(c)): Caution[] {
  return cautions.filter(k => !c.seen.includes(k.key))
}

/** The words for a caution, without the "Quack:" prefix. */
export function cautionText(k: Caution, locale: Locale): string {
  switch (k.kind) {
    case 'check':
      return t(locale, 'caution.check', { kind: t(locale, `kind.${k.checkKind ?? 'test'}`) })
    case 'five':
      return t(locale, 'caution.five', { pct: formatPercent(k.pct) })
    case 'context':
      return k.left !== undefined ? t(locale, 'caution.compact', { left: formatTokens(k.left) }) : t(locale, 'caution.context', { pct: formatPercent(k.pct) })
    case 'runaway':
      return t(locale, 'caution.runaway', { n: k.turn ?? 0, x: k.factor !== undefined ? k.factor.toFixed(1) : '3+' })
  }
}

/**
 * The caution in at most `room` columns, for the band's duck: its words where
 * they fit, else their short form (`5h at 84%`, `turn 12: 3.4×`), never a
 * reading cut off.
 */
export function cautionFit(k: Caution, locale: Locale, room: number): string {
  const long = cautionText(k, locale)
  if (displayWidth(long) <= room) return long
  switch (k.kind) {
    case 'check':
      return fit(t(locale, 'caution.check', { kind: t(locale, `kindShort.${k.checkKind ?? 'test'}`) }), room)
    case 'five':
      return fit(t(locale, 'caution.fiveShort', { pct: formatPercent(k.pct) }), room)
    case 'context':
      return fit(k.left !== undefined ? long : t(locale, 'caution.contextShort', { pct: formatPercent(k.pct) }), room)
    case 'runaway':
      return fit(t(locale, 'caution.runawayShort', { n: k.turn ?? 0, x: k.factor !== undefined ? k.factor.toFixed(1) : '3+' }), room)
  }
}

export function quackLine(k: Caution, locale: Locale): string {
  return `${t(locale, 'duck.quack')} ${cautionText(k, locale)}`
}

/** The per-day notification counter as the store keeps it. */
export type NotifyRecord = { day: string; count: number }

/** Takes one of the day's 3 notification slots, if one is left. */
export function takeNotifySlot(record: NotifyRecord | undefined, day: string): { record: NotifyRecord; isTaken: boolean } {
  const current = record && record.day === day ? record : { day, count: 0 }
  if (current.count >= NOTIFY_PER_DAY) return { record: current, isTaken: false }
  return { record: { day, count: current.count + 1 }, isTaken: true }
}

/** Gives a slot back when the notification did not go out. */
export function returnNotifySlot(record: NotifyRecord | undefined, day: string): NotifyRecord {
  if (!record || record.day !== day) return { day, count: 0 }
  return { day, count: Math.max(0, record.count - 1) }
}

files.src/format.ts:
// Numbers, money, durations and clock times as the band and the handover
// print them. Pure; locale-aware only where words are involved.

import { t, type Locale } from './i18n'
import { HOUR, MINUTE } from './metrics'

/** 950, 12.3k, 340k, 1.2M, 15M. */
export function formatTokens(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return '0'
  if (n < 1000) return String(Math.round(n))
  if (n < 10_000) return `${trim1(n / 1000)}k`
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`
  if (n < 10_000_000) return `${trim1(n / 1_000_000)}M`
  return `${Math.round(n / 1_000_000)}M`
}

function trim1(x: number): string {
  const s = x.toFixed(1)
  return s.endsWith('.0') ? s.slice(0, -2) : s
}

/** $0.004, $0.42, $3.10, $12.4, $128. */
export function formatUsd(usd: number | undefined): string {
  if (usd === undefined || !Number.isFinite(usd)) return '—'
  const v = Math.max(0, usd)
  if (v === 0) return '$0'
  // Under a tenth of a cent it would round to $0.000, which reads as nothing spent.
  if (v < 0.0005) return '<$0.001'
  if (v < 0.01) return `$${v.toFixed(3)}`
  if (v < 10) return `$${v.toFixed(2)}`
  if (v < 100) return `$${v.toFixed(1)}`
  return `$${Math.round(v)}`
}

/** 0.4 s, 3.1 s, 42 s, 4m 05s, 1h 12m. */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return '—'
  if (ms < 10_000) return `${(ms / 1000).toFixed(1)} s`
  if (ms < MINUTE) return `${Math.round(ms / 1000)} s`
  if (ms < HOUR) {
    const m = Math.floor(ms / MINUTE)
    const s = Math.floor((ms % MINUTE) / 1000)
    return `${m}m ${String(s).padStart(2, '0')}s`
  }
  const h = Math.floor(ms / HOUR)
  const m = Math.floor((ms % HOUR) / MINUTE)
  return `${h}h ${String(m).padStart(2, '0')}m`
}

/** A turn clock: 0:42, 3:05, 1:12:09. */
export function formatClock(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  const ss = String(s).padStart(2, '0')
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`
}

/**
 * A length in whole minutes, for what is still going or shown on a 30-second
 * redraw: <1m, 4m, 1h12m. Nothing in the band ticks seconds.
 */
export function formatMinutes(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return '—'
  const min = Math.floor(ms / MINUTE)
  if (min < 1) return '<1m'
  if (min < 60) return `${min}m`
  return `${Math.floor(min / 60)}h${String(min % 60).padStart(2, '0')}m`
}

/** A finished length as the pane's task and agent rows print it: 4m12, 52s, 1h04m. */
export function formatSpan(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return '—'
  const s = Math.floor(ms / 1000)
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m${String(s % 60).padStart(2, '0')}`
  return `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

/** An estimate of time left, whole minutes, never finer: 9m, 1h20m. The caller adds the `~`. */
export function formatLeft(ms: number): string {
  const min = Math.max(1, Math.round(ms / MINUTE))
  return min < 60 ? `${min}m` : `${Math.floor(min / 60)}h${String(min % 60).padStart(2, '0')}m`
}

/** A countdown in whole minutes: 45m, 1h12, 3d4h. */
export function formatCountdown(ms: number): string {
  if (!Number.isFinite(ms)) return '—'
  const min = Math.max(0, Math.ceil(ms / MINUTE))
  if (min < 60) return `${min}m`
  const h = Math.floor(min / 60)
  if (h < 24) return `${h}h${String(min % 60).padStart(2, '0')}`
  const d = Math.floor(h / 24)
  return `${d}d${h % 24}h`
}

/** Local wall-clock time, 24-hour: 14:52. */
export function clockText(at: number): string {
  const d = new Date(at)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

/** Local date and time for the handover: 2026-10-11 14:52. */
export function stampText(at: number): string {
  const d = new Date(at)
  const date = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  return `${date} ${clockText(at)}`
}

/** The local calendar day of a moment, as YYYY-MM-DD. */
export function dayKey(at: number): string {
  const d = new Date(at)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

/** How long ago, in whole minutes: just now, 4 min ago, 2 h ago, in the person's language. No seconds: the band redraws every 30 s. */
export function formatAge(ms: number, locale: Locale): string {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return t(locale, 'age.now')
  if (s < 3600) return t(locale, 'age.min', { n: Math.floor(s / 60) })
  if (s < 86_400) return t(locale, 'age.hour', { n: Math.floor(s / 3600) })
  return t(locale, 'age.day', { n: Math.floor(s / 86_400) })
}

/** 0 to 100 as a whole percent; one decimal under 10 when it has one. */
export function formatPercent(pct: number | undefined): string {
  if (pct === undefined || !Number.isFinite(pct)) return '—'
  const v = Math.max(0, pct)
  if (v < 10 && Math.round(v * 10) % 10 !== 0) return `${v.toFixed(1)}%`
  return `${Math.round(v)}%`
}

/** Cuts text to `max` characters on a word boundary where one is near, with an ellipsis. */
export function clip(text: string, max: number): string {
  const one = text.replace(/\s+/g, ' ').trim()
  if (one.length <= max) return one
  if (max <= 1) return '…'
  const cut = one.slice(0, max - 1)
  const space = cut.lastIndexOf(' ')
  return `${space > max * 0.6 ? cut.slice(0, space) : cut}…`
}

/**
 * A long text cut to about `max` characters, its lines kept: the head (where a
 * request or a plan says what it is) and the tail, an ellipsis line between.
 */
export function squeeze(text: string, max: number): string {
  const whole = text.trim()
  if (whole.length <= max) return whole
  const head = Math.ceil(max * 0.6)
  return `${whole.slice(0, head).trimEnd()}\n…\n${whole.slice(whole.length - (max - head)).trimStart()}`
}

/**
 * Words added to words kept so far, held to `max` characters: once over, the
 * first `head` stay (a plan is said first) and the latest fill the rest, so a
 * long turn's words stay as long as this however often they are added to.
 */
export function addWords(kept: string | undefined, words: string, max = 1600, head = 900): string {
  const more = words.trim()
  if (more === '') return kept ?? ''
  const joined = kept ? `${kept}\n${more}` : more
  if (joined.length <= max) return joined
  // Untrimmed, so the head is the same 900 characters every time and the ellipsis never reaches the tail.
  return `${joined.slice(0, head)}\n…\n${joined.slice(joined.length - (max - head - 3))}`
}

/** The last segment of a path. */
export function baseName(path: string): string {
  const parts = path.split(/[\\/]/).filter(Boolean)
  return parts.at(-1) ?? path
}

/** A path shown relative to the project root when it lies under it. */
export function relativePath(path: string, root: string | undefined): string {
  if (!root) return path
  const r = root.endsWith('/') ? root : `${root}/`
  return path.startsWith(r) ? path.slice(r.length) : path
}

files.src/gauges.ts:
// The gauges as drawings, for each way a surface can show them:
//   - text: lines of block characters in theme colours, which any terminal
//     draws the same way: a tachometer ramp of eighth blocks for pace, a
//     half-block ring for context. The designed fallback.
//   - cells: a Raster for what needs two colours in a cell (the duck).
//   - pixels: an RGBA Image the terminal shows where it speaks the kitty
//     graphics protocol (kitty, Ghostty): a needle dial, a smooth ring.
// The SVG variant for the desktop lives in svg.ts. A graphic is described
// once (`Graphic`) and every drawer reads the same description. Pure.

import { quadrantCells, type RasterCells } from './cells'
import type { Level } from './derive'
import { hex, PixelCanvas, type ImageSource, type Rgba } from './pixels'
import { DUCK_12x4, DUCK_16, DUCK_8x2, DUCK_COLUMNS, DUCK_RGBA, IDLE_EYE, spritePixels, STEADY, type Frame, type Pose } from './sprites'
import type { Line, Span, Tone } from './text'

export type Graphic =
  | { kind: 'dial'; cols: number; rows: number; needle?: number; isGrey: boolean; warnFrom: number; badFrom: number; sweep?: number; bug?: number; needleLevel?: Level; noZones?: boolean }
  | { kind: 'ring'; cols: number; rows: number; pct?: number; level: Level }
  | { kind: 'duck'; cols: number; rows: number; pose: Pose }

/** Threshold colours for pictures, mid-tones that read on dark and light themes alike. */
export const HEX = {
  ok: '#3fb950',
  warn: '#e3a008',
  bad: '#f85149',
  track: '#6e7681',
  grey: '#8b949e',
  /** A needle and a ring's fill: light enough for dark themes, dark enough for light ones. */
  neutral: '#a3acb7',
} as const

function levelTone(level: Level): Tone | undefined {
  return level === 'bad' ? 'bad' : level === 'warn' ? 'warn' : level === 'ok' ? 'ok' : undefined
}

const EIGHTHS = ' ▁▂▃▄▅▆▇█'

// ------------------------------------------------------------------ text

/** Spans of one character each, merged where neighbours share a look. */
function merge(spans: Span[]): Line {
  const out: Line = []
  for (const s of spans) {
    const last = out.at(-1)
    if (last && last.tone === s.tone && last.bg === s.bg && last.bold === s.bold) last.text += s.text
    else out.push({ ...s })
  }
  return out
}

/**
 * A dial as a tachometer: `cols` bars rising left to right over `rows` rows,
 * lit up to the needle; the lead bar is the needle itself. The caution and
 * red zones are lit in their colours (or, on a dial with no zones, every lit
 * bar takes the needle's threshold colour), and with too little data every
 * lit bar is grey. A sweep (the fuel gauge's trend to its reset) lights the
 * bars beyond the needle in grey up to its end; the bug's bar is the accent.
 */
export function rampLines(g: Extract<Graphic, { kind: 'dial' }>): Line[] {
  const n = g.cols
  const eighths = g.rows * 8
  const lit = g.needle === undefined ? 0 : Math.max(g.needle > 0 ? 1 : 0, Math.round(g.needle * n))
  const sweep = g.sweep === undefined || g.isGrey ? lit : Math.max(lit, Math.round(Math.min(1, g.sweep) * n))
  const bug = g.bug === undefined ? -1 : Math.min(n - 1, Math.floor(g.bug * n))
  const needleTone = levelTone(g.needleLevel ?? 'none')
  const lines: Span[][] = Array.from({ length: g.rows }, () => [])
  for (let i = 0; i < n; i++) {
    const height = Math.max(1, Math.round((eighths * (i + 1)) / n))
    const f = (i + 0.5) / n
    let tone: Tone | undefined
    if (i >= lit) tone = i === bug ? 'accent' : i < sweep ? 'grey' : 'track'
    else if (g.isGrey) tone = 'grey'
    else if (g.noZones) tone = needleTone
    else tone = f >= g.badFrom ? 'bad' : f >= g.warnFrom ? 'warn' : undefined
    const isNeedle = i === lit - 1 && !g.isGrey
    for (let row = 0; row < g.rows; row++) {
      // Row 0 is the top: it holds what is left above the rows beneath it.
      const below = (g.rows - 1 - row) * 8
      const part = Math.max(0, Math.min(8, height - below))
      lines[row]?.push({ text: EIGHTHS[part] ?? ' ', ...(tone ? { tone } : {}), ...(isNeedle ? { bold: true } : {}) })
    }
  }
  return lines.map(merge)
}

/** The ring's outline, clockwise from 12 o'clock, on a `w` x `h` pixel grid. */
export function ringPixels(w: number, h: number): [number, number][] {
  const top: [number, number][] = []
  for (let x = 1; x < w - 1; x++) top.push([x, 0])
  const right: [number, number][] = []
  for (let y = 1; y < h - 1; y++) right.push([w - 1, y])
  const bottom: [number, number][] = []
  for (let x = w - 2; x > 0; x--) bottom.push([x, h - 1])
  const left: [number, number][] = []
  for (let y = h - 2; y > 0; y--) left.push([0, y])
  const ring = [...top, ...right, ...bottom, ...left]
  const start = Math.floor((w - 2) / 2)
  return [...ring.slice(start), ...ring.slice(0, start)]
}

/**
 * Context as a ring of half-block pixels (`cols` wide, `rows * 2` tall),
 * filled clockwise from the top in the level's colour, the rest unlit.
 */
export function ringLines(g: Extract<Graphic, { kind: 'ring' }>): Line[] {
  const w = g.cols
  const h = g.rows * 2
  const ring = ringPixels(w, h)
  const pct = Math.max(0, Math.min(100, g.pct ?? 0))
  const lit = Math.round((ring.length * pct) / 100)
  const tone = levelTone(g.level)
  const grid: (Tone | 'lit' | undefined)[][] = Array.from({ length: h }, () => Array.from({ length: w }, () => undefined))
  ring.forEach(([x, y], i) => {
    const row = grid[y]
    if (row) row[x] = i < lit ? (tone ?? 'lit') : 'track'
  })
  const lines: Line[] = []
  for (let cy = 0; cy < g.rows; cy++) {
    const spans: Span[] = []
    for (let x = 0; x < w; x++) {
      const top = grid[cy * 2]?.[x]
      const bottom = grid[cy * 2 + 1]?.[x]
      const as = (t: Tone | 'lit'): Tone | undefined => (t === 'lit' ? undefined : t)
      if (top === undefined && bottom === undefined) spans.push({ text: ' ' })
      else if (top !== undefined && bottom !== undefined) {
        if (top === bottom) spans.push({ text: '█', ...(as(top) ? { tone: as(top) } : {}) })
        else spans.push({ text: '▀', ...(as(top) ? { tone: as(top) } : {}), ...(as(bottom) ? { bg: as(bottom) } : {}) })
      } else if (top !== undefined) spans.push({ text: '▀', ...(as(top) ? { tone: as(top) } : {}) })
      else if (bottom !== undefined) spans.push({ text: '▄', ...(as(bottom) ? { tone: as(bottom) } : {}) })
    }
    lines.push(merge(spans))
  }
  return lines
}

/** A graphic as text lines, for surfaces drawing designed text. The duck has none. */
export function graphicLines(g: Graphic): Line[] | undefined {
  if (g.kind === 'dial') return rampLines(g)
  if (g.kind === 'ring') return ringLines(g)
  return undefined
}

// ------------------------------------------------------------------ cells

/** The duck as Raster cells: a frame of the 2-row duck (12x4 in quadrants, 6 columns), or the one-row band's 4 columns. */
export function duckCells(frame: Frame, rows: 1 | 2): RasterCells {
  if (rows === 1) return quadrantCells(spritePixels(DUCK_8x2), 8)
  return quadrantCells(spritePixels(DUCK_12x4[frame]), 12, frame === 'idle' ? IDLE_EYE : {})
}

// ------------------------------------------------------------------ pixels

/** Pixels per cell for the Image variant: twice the usual 8x16 cell, for sharp edges. */
export const PX_W = 16
export const PX_H = 32

function levelRgba(level: Level, fallback: Rgba): Rgba {
  return level === 'bad' ? hex(HEX.bad) : level === 'warn' ? hex(HEX.warn) : level === 'ok' ? hex(HEX.ok) : fallback
}

const dialAngle = (f: number) => Math.PI * (1 - Math.max(0, Math.min(1, f)))

/** A needle gauge: caution and red arcs, five ticks, the needle grey with too little data. */
export function dialImage(g: Extract<Graphic, { kind: 'dial' }>): ImageSource {
  const w = g.cols * PX_W
  const h = g.rows * PX_H
  const canvas = new PixelCanvas(w, h)
  const cx = w / 2
  const cy = h - 7
  const thick = Math.max(3, Math.round(h / 11))
  const r = Math.min(w / 2 - thick - 2, cy - thick - 2)
  canvas.arc(cx, cy, r, thick, 0, Math.PI, hex(HEX.track, 150))
  canvas.arc(cx, cy, r, thick, dialAngle(g.badFrom), dialAngle(g.warnFrom), hex(HEX.warn))
  canvas.arc(cx, cy, r, thick, 0, dialAngle(g.badFrom), hex(HEX.bad))
  for (const f of [0, 0.25, 0.5, 0.75, 1]) {
    const a = dialAngle(f)
    const inner = r - thick - (f === 0.5 ? 5 : 3)
    canvas.line(cx + inner * Math.cos(a), cy - inner * Math.sin(a), cx + (r - thick) * Math.cos(a), cy - (r - thick) * Math.sin(a), f === 0.5 ? 2.5 : 1.5, hex(HEX.grey, 200))
  }
  // With too little data the needle is a faint grey; otherwise solid.
  const needleColor = g.isGrey ? hex(HEX.grey, 110) : hex(HEX.neutral)
  const a = dialAngle(g.isGrey || g.needle === undefined ? 0 : g.needle)
  canvas.line(cx, cy, cx + (r - 2) * Math.cos(a), cy - (r - 2) * Math.sin(a), 3, needleColor)
  canvas.disc(cx, cy, 5, needleColor)
  return canvas.toSource()
}

export function ringImage(g: Extract<Graphic, { kind: 'ring' }>): ImageSource {
  const w = g.cols * PX_W
  const h = g.rows * PX_H
  const canvas = new PixelCanvas(w, h)
  const size = Math.min(w, h)
  const thick = Math.max(5, Math.round(size / 7))
  const r = size / 2 - thick / 2 - 2
  const cx = w / 2
  const cy = h / 2
  canvas.arc(cx, cy, r, thick, 0, 2 * Math.PI, hex(HEX.track, 110))
  const pct = Math.max(0, Math.min(100, g.pct ?? 0))
  if (pct > 0) {
    const start = Math.PI / 2 - (2 * Math.PI * pct) / 100
    canvas.arc(cx, cy, r, thick, start, Math.PI / 2, levelRgba(g.level, hex(HEX.neutral)))
  }
  return canvas.toSource()
}

/** The 16x16 duck at four pixels a pixel, centred in its 2-row cell's own shape so the terminal does not stretch it. */
export function duckImage(pose: Frame): ImageSource {
  const width = DUCK_COLUMNS * PX_W
  const canvas = new PixelCanvas(width, 2 * PX_H)
  canvas.sprite(DUCK_16[pose], DUCK_RGBA, Math.floor((width - 64) / 2), 0, 4)
  return canvas.toSource()
}

export function graphicImage(g: Graphic): ImageSource {
  switch (g.kind) {
    case 'dial':
      return dialImage(g)
    case 'ring':
      return ringImage(g)
    case 'duck':
      return duckImage(STEADY[g.pose])
  }
}

/** A 1x1 clear pixel: what the band blits once to learn whether images show. */
export function probeImage(): ImageSource {
  return new PixelCanvas(1, 1).toSource()
}

