// Waits on the person: the time Claude spends waiting for an answer is not
// work. A wait is a question Claude asked (AskUserQuestion), a plan put up for
// approval (ExitPlanMode), or a permission dialog that really showed (one no
// hook and no auto-mode classifier settled by itself). It holds the loop that
// asked, and the main loop too when that loop is a subagent the main loop
// waits on in the foreground. Lengths quackpit measures leave the held time
// out, and an expected end moves later by it: the work's own clock stands
// still while it waits. Pure.

/** A question put to the person, a plan to approve, or a permission dialog. */
export type WaitKind = 'question' | 'plan' | 'permission'

export type Wait = {
  from: number
  /** When it ended; absent while it is open. */
  to?: number
  kind: WaitKind
  /** The tool the dialog is for (`Bash`; `AskUserQuestion` for a question). */
  tool?: string
  /** The call it holds, when that is known. */
  toolUseId?: string
  /** A subagent's dialog: its loop's id. Absent for the main loop's. */
  agentId?: string
  /** The subagent's type, for the words (`Explore`). */
  agentType?: string
  /** Whether it holds the main loop: its own, or a foreground subagent's the main loop waits on. */
  main: boolean
}

/** Closed waits kept: enough to cover the open work's lengths; the open ones are always kept. */
export const MAX_WAITS = 40

/** Whose clock a wait holds: the main loop's, or one subagent's (by its loop id). */
export type Clock = 'main' | { agentId: string }

function holds(w: Wait, clock: Clock): boolean {
  return clock === 'main' ? w.main : w.agentId === clock.agentId
}

/** The waits open now, the newest last. */
export function openWaits(waits: readonly Wait[] | undefined, clock?: Clock): Wait[] {
  return (waits ?? []).filter(w => w.to === undefined && (clock === undefined || holds(w, clock)))
}

/** The wait that holds `clock` now, if any: the one that opened first, whose length the words give. */
export function waitingNow(waits: readonly Wait[] | undefined, clock: Clock = 'main'): Wait | undefined {
  return openWaits(waits, clock)[0]
}

/**
 * Milliseconds of [from, to] that waits holding `clock` covered, an open one
 * up to `to`. Waits that overlap count once.
 */
export function heldMs(waits: readonly Wait[] | undefined, from: number, to: number, clock: Clock = 'main'): number {
  if (!(to > from)) return 0
  const spans = (waits ?? [])
    .filter(w => holds(w, clock))
    .map(w => [Math.max(from, w.from), Math.min(to, w.to ?? to)] as const)
    .filter(([a, b]) => b > a)
    .sort((x, y) => x[0] - y[0])
  let total = 0
  let end = -Infinity
  for (const [a, b] of spans) {
    if (b <= end) continue
    total += b - Math.max(a, end)
    end = b
  }
  return total
}

/** The time between `from` and `to` that was work: the waits holding `clock` left out. */
export function activeMs(waits: readonly Wait[] | undefined, from: number, to: number, clock: Clock = 'main'): number {
  return Math.max(0, to - from - heldMs(waits, from, to, clock))
}

/** The ledger with one more wait open, the oldest closed ones past the limit dropped. */
export function startWait(waits: readonly Wait[] | undefined, w: Wait): Wait[] {
  const all = [...(waits ?? []).filter(x => !(x.to === undefined && w.toolUseId !== undefined && x.toolUseId === w.toolUseId)), w]
  const closed = all.filter(x => x.to !== undefined)
  const drop = new Set(closed.slice(0, Math.max(0, closed.length - MAX_WAITS)))
  return all.filter(x => !drop.has(x))
}

/** Which open waits a closing applies to: one call's, one loop's, or every one. */
export type WaitMatch = { toolUseId: string } | { agentId: string | undefined } | 'all'

function matches(w: Wait, match: WaitMatch): boolean {
  if (match === 'all') return true
  if ('toolUseId' in match) return w.toolUseId === match.toolUseId
  return w.agentId === match.agentId
}

/** The ledger with the matching open waits closed at `at`; the same array when none was open. */
export function endWaits(waits: readonly Wait[] | undefined, match: WaitMatch, at: number): Wait[] {
  const list = waits ?? []
  if (!list.some(w => w.to === undefined && matches(w, match))) return [...list]
  return list.map(w => (w.to === undefined && matches(w, match) ? { ...w, to: Math.max(w.from, at) } : w))
}

/** Waits read back from storage: anything not in a wait's shape is dropped. */
export function asWaits(x: unknown): Wait[] {
  if (!Array.isArray(x)) return []
  return x.filter((w): w is Wait => {
    if (typeof w !== 'object' || w === null) return false
    const r = w as Record<string, unknown>
    return typeof r.from === 'number' && Number.isFinite(r.from) && (r.to === undefined || typeof r.to === 'number') && (r.kind === 'question' || r.kind === 'plan' || r.kind === 'permission') && typeof r.main === 'boolean'
  })
}

files.src/details.ts:
// What a cell of the pane's grid, or one of its two dials, opens under the
// grid when pressed: the tile at length, from what quackpit already keeps.
// The pace's samples and its usual; the five-hour window's readings, its fit
// and their age; the context turn by turn with its compactions; the turns by
// cost; every check run with its failing lines; every subagent run; every
// edited file; the session's model, effort, mode and time; and health's
// parts, each with its value, rule, weight and what it took off. Host-neutral
// lines; the adapter draws them. Pure.

import { judgedKinds, kindsOf, type CheckResult } from './checks'
import { FIT_SPAN_MS, FIVE_HOUR_MS, fuelGauge, PACE_WARN_RATIO, PACE_BAD_RATIO, sevenDayForecast, type Level } from './derive'
import { baseName, clockText, formatAge, formatCountdown, formatDuration, formatMinutes, formatPercent, formatSpan, formatTokens, formatUsd, relativePath } from './format'
import { partName, partRule, partValue, wordText } from './health'
import { t, type Locale } from './i18n'
import { hitRatio, median, MINUTE, PACE_WINDOW_MS } from './metrics'
import { SETUP_KEYS, SOURCE_COLORS, sourceTokens, type SetupKey, type SourceId } from './context'
import { contextNow, contextShare, unverified, type AgentRun } from './model'
import { columnChart, displayWidth, fit, fitLine, lineWidth, pad, sparkline, wrapLine, type Line, type Span, type Tone } from './text'
import { checkSummary, kindsText, modelOf, projectionSpans, type Readings, type TileId } from './tiles'

/** What a press opens: any tile's but the hero's, whose detail is the timeline tab; pace and limits are the dials'. */
export type DetailId = Exclude<TileId, 'progress'>

export type Detail = {
  id: DetailId
  /** After the tile's name: the headline figure and what it is. */
  title: Line
  lines: Line[]
}

const muted = (text: string): Span => ({ text, tone: 'muted' })
/** A sentence of quackpit's own, wrapped whole over at most three lines rather than cut. */
const para = (text: string, width: number, tone: Tone = 'muted'): Line[] => wrapLine([{ text, tone }], width, 3)
const toneOf = (level: Level): Tone | undefined => (level === 'bad' ? 'bad' : level === 'warn' ? 'warn' : level === 'ok' ? 'ok' : undefined)
/** Whole minutes as hours and minutes: 45m, 3h12. */
const hm = (ms: number) => {
  const min = Math.max(0, Math.floor(ms / MINUTE))
  return min < 60 ? `${min}m` : `${Math.floor(min / 60)}h${String(min % 60).padStart(2, '0')}`
}

/** What the details need beyond the readings: the project root for paths. */
export type DetailExtra = { root?: string }

export function detailOf(r: Readings, id: DetailId, width: number, extra: DetailExtra = {}): Detail {
  const w = Math.max(24, width)
  const detail = DETAILS[id](r, w, extra)
  return { ...detail, lines: detail.lines.map(line => fitLine(line, w)) }
}

const DETAILS: Record<DetailId, (r: Readings, width: number, extra: DetailExtra) => Detail> = {
  pace: paceDetail,
  limits: windowDetail,
  context: contextDetail,
  cost: costDetail,
  checks: checksDetail,
  files: filesDetail,
  agents: agentsDetail,
  session: sessionDetail,
  health: healthDetail,
}

/** A chart's lines set in from the left, with its two ends named under it. */
function charted(chart: Line[], left: string, right: string, width: number): Line[] {
  const inner = Math.max(...chart.map(lineWidth), 0)
  const gap = Math.max(1, inner - displayWidth(left) - displayWidth(right))
  return [...chart.map(line => [{ text: '  ' }, ...line]), [muted(`  ${left}${' '.repeat(gap)}${right}`)]].map(line => fitLine(line, width))
}

// ------------------------------------------------------------------ the dials

function paceDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c, ctx, pace: p } = r
  const tone = p.ratio !== undefined && p.ratio >= PACE_BAD_RATIO ? 'bad' : p.ratio !== undefined && p.ratio >= PACE_WARN_RATIO ? 'warn' : undefined
  const title: Line = [{ text: t(L, 'detail.pace.now', { pace: t(L, 'pace.perHour', { tokens: formatTokens(p.perHour) }) }), bold: true, ...(tone ? { tone } : {}) }]
  const lines: Line[] = [...para(t(L, 'detail.pace.what'), width)]
  // The last hour, a column a stretch of minutes, from the one-a-minute samples.
  const columns = width >= 48 ? 30 : 20
  const span = PACE_WINDOW_MS / columns
  const from = ctx.now - PACE_WINDOW_MS
  const buckets = Array.from({ length: columns }, () => 0)
  for (const [at, tokens] of c.recent) {
    const i = Math.floor((at - from) / span)
    if (i >= 0 && i < columns) buckets[i] = (buckets[i] ?? 0) + tokens
  }
  if (buckets.some(v => v > 0)) lines.push(...charted(columnChart(buckets, Math.max(...buckets), 3, () => undefined, 1), t(L, 'detail.pace.hourAgo'), t(L, 'detail.now'), width))
  else lines.push(...para(t(L, 'detail.pace.none'), width))
  lines.push([{ text: t(L, 'detail.pace.hour', { tokens: formatTokens(p.hourSum) }) }])
  if (!p.hasData) lines.push(...para(t(L, 'detail.pace.warming'), width))
  // Against what: your last days, or this session's own average until 3 days are kept.
  const usual = p.usual !== undefined ? t(L, 'pace.perHour', { tokens: formatTokens(p.usual) }) : undefined
  const days = ctx.days.filter(d => d.day < ctx.today && d.activeMin > 0 && d.tokens > 0).slice(-14)
  const activeMin = Math.floor(c.activeMs / MINUTE)
  if (p.ratio !== undefined && usual !== undefined) {
    const ratio = p.usualBasis === 'session' ? t(L, 'detail.pace.ratioSession', { x: p.ratio.toFixed(1), usual }) : t(L, 'detail.pace.ratio', { x: p.ratio.toFixed(1), usual })
    lines.push(...wrapLine([{ text: ratio, ...(tone ? { tone } : {}) }], width, 2))
  } else lines.push([muted(t(L, 'dial.noUsual'))])
  lines.push(...para(days.length >= 3 ? t(L, 'detail.pace.usualDays', { n: days.length }) : activeMin >= 10 ? t(L, 'detail.pace.usualSession', { n: activeMin }) : t(L, 'detail.pace.usualNone'), width))
  if (p.idleMs !== undefined && p.idleMs >= MINUTE) lines.push(...para(t(L, 'detail.pace.idle', { time: formatMinutes(p.idleMs) }), width))
  // The scale's two ends and its marks, which no longer sit under the dial.
  if (usual !== undefined && p.usual !== undefined) lines.push(...para(t(L, 'detail.pace.scale', { max: t(L, 'pace.perHour', { tokens: formatTokens(2 * p.usual) }), usual }), width))
  const hits = hitRatio(c.cache)
  if (hits !== undefined) lines.push(...para(t(L, 'detail.pace.cache', { pct: formatPercent(100 * hits) }), width))
  if (c.lastStep) lines.push(...para(t(L, 'detail.pace.latest', { age: formatAge(ctx.now - c.lastStep.at, L) }), width))
  return { id: 'pace', title, lines }
}

function windowDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c, ctx } = r
  const now = ctx.now
  const five = c.reading?.fiveHour
  const g = fuelGauge(c, now)
  if (!five || !g) return { id: 'limits', title: [muted('—')], lines: para(t(L, 'detail.window.none'), width) }
  const title: Line = [{ text: t(L, 'dial.used', { pct: formatPercent(g.pct) }), bold: true, ...(toneOf(g.level) ? { tone: toneOf(g.level) } : {}) }, muted(` · ${t(L, 'dial.fiveWhat')}`)]
  const lines: Line[] = []
  if (g.isReset) lines.push(...para(t(L, 'detail.window.reset'), width))
  else {
    if (g.resetsAt !== undefined) lines.push([{ text: t(L, 'detail.window.resets', { time: clockText(g.resetsAt), in: formatCountdown(g.resetsAt - now) }) }])
    if (g.elapsed !== undefined) lines.push(...para(t(L, 'detail.window.elapsed', { gone: hm(g.elapsed * FIVE_HOUR_MS) }), width))
    if (g.isUsedUp && g.resetsAt !== undefined) lines.push([{ text: t(L, 'dial.usedUp', { time: clockText(g.resetsAt) }), tone: 'bad' }])
    else if (g.emptiesAt !== undefined && g.resetsAt !== undefined) lines.push(...wrapLine([{ text: t(L, 'detail.window.runsOut', { time: clockText(g.emptiesAt), left: formatCountdown(g.resetsAt - g.emptiesAt), reset: clockText(g.resetsAt) }), tone: toneOf(g.level) ?? 'warn' }], width, 2))
    else if (g.atReset !== undefined) lines.push(...para(t(L, 'detail.window.atReset', { pct: formatPercent(Math.min(100, g.atReset)) }), width))
    // The rate, here alone, in plain words.
    const readAt = c.reading?.at ?? now
    const fitted = c.fiveSamples.filter(([at]) => at > readAt - FIT_SPAN_MS && at <= readAt).length
    if (g.rate !== undefined) {
      const points = g.rate < 10 ? (Math.round(g.rate * 10) / 10).toString() : Math.round(g.rate).toString()
      // Both wrap whole: found cut at 56 to 64 columns while the rate was still the window's average.
      lines.push(...wrapLine([{ text: t(L, g.how === 'fit' ? 'detail.window.rate' : 'detail.window.rateAverage', { points }) }], width, 2))
      lines.push(...wrapLine([muted(t(L, g.how === 'fit' ? 'detail.window.rateWhat' : 'detail.window.rateWhatAverage', { n: fitted, points }))], width, 5))
    } else lines.push([muted(t(L, 'dial.measuring'))])
  }
  // The readings the trend goes through, oldest first: the last six, a minute's same reading once.
  const samples = c.fiveSamples.map(([at, pct]) => `${clockText(at)} ${formatPercent(pct)}`).filter((label, i, all) => label !== all[i - 1]).slice(-6)
  if (samples.length > 0) lines.push(...wrapLine([muted(`${t(L, 'detail.window.readings')} ${samples.join(' · ')}`)], width, 2))
  const seven = c.reading?.sevenDay
  if (seven) {
    // Where the week is heading: `→ ~61%`, or when it runs out before its own reset.
    const parts = [t(L, 'detail.window.seven', { pct: formatPercent(seven.pct) }), ...(seven.resetsAt !== undefined ? [t(L, 'detail.window.sevenResets', { in: formatCountdown(seven.resetsAt - now) })] : [])]
    lines.push([{ text: parts.join(' · ') }, ...projectionSpans(seven, sevenDayForecast(c), L, now)])
  }
  lines.push(...para(t(L, 'detail.window.scale'), width))
  lines.push(...para(t(L, 'detail.window.age', { age: formatAge(now - g.asOf, L) }), width))
  return { id: 'limits', title, lines }
}

// ------------------------------------------------------------------ the cells

/** The context's chart is drawn against its auto-compact point once a turn came this near it; before, against the turns. */
const CHART_NEAR = 0.5

/** A row of the sources' table: a swatch, a name padded to `nameW`, the tokens right-aligned, the share. */
function sourceRow(swatch: Span | undefined, name: string, nameW: number, tokens: string, share: string | undefined, indent = 0): Line {
  return [
    { text: ' '.repeat(indent) },
    ...(swatch ? [swatch, { text: ' ' }] : [{ text: '  ' }]),
    { text: pad(name, nameW) },
    { text: tokens.padStart(7) },
    ...(share !== undefined ? [muted(share.padStart(5))] : []),
  ]
}

/**
 * What fills the context, at length: every source with its tokens and share,
 * the largest first, setup's own rows under it (with the MCP servers and the
 * memory files), and the largest single parts. The setup rows and the
 * Messages row are /context's own figures; the split of Messages is
 * quackpit's, with `~`.
 */
function contextSplitLines(r: Readings, width: number): Line[] {
  const L = r.ctx.locale
  const split = r.c.ctx
  if (!split || sourceTokens(split).length === 0) return para(t(L, 'detail.context.noSplit'), width)
  const lines: Line[] = []
  lines.push(...para(t(L, 'detail.context.split', { time: clockText(split.at) }), width))
  const sources = sourceTokens(split)
  const total = sources.reduce((sum, s) => sum + s.tokens, 0)
  const name = (id: SourceId) => t(L, `ctx.src.${id}`)
  const setupName = (key: string) => ((SETUP_KEYS as readonly string[]).includes(key) ? t(L, `ctx.setup.${key as SetupKey}`) : key)
  const nameW = Math.min(Math.max(...sources.map(s => displayWidth(name(s.id))), ...split.setup.map(row => displayWidth(setupName(row.key)) + 2), 8) + 2, Math.max(10, width - 16))
  const share = (tokens: number) => (total > 0 ? `${Math.round((100 * tokens) / total)}%` : '')
  for (const s of sources) {
    const swatch: Span = { text: '■', color: SOURCE_COLORS[s.id] }
    // Setup's figure is /context's; the rest is quackpit's split of its Messages row.
    lines.push(sourceRow(swatch, name(s.id), nameW, s.id === 'setup' ? formatTokens(s.tokens) : `~${formatTokens(s.tokens)}`, share(s.tokens)))
    if (s.id !== 'setup') continue
    for (const row of [...split.setup].sort((a, b) => b.tokens - a.tokens)) {
      const extra =
        row.key === 'mcp' && split.mcp
          ? split.mcp.map(([server, tokens]) => `${server} ${formatTokens(tokens)}`).join(' · ')
          : row.key === 'agents' && split.agentCount
            ? t(L, split.agentCount === 1 ? 'detail.context.agent' : 'detail.context.agents', { n: split.agentCount })
            : row.key === 'skills' && split.skills
              ? t(L, 'detail.context.skills', { n: split.skills.included, total: split.skills.total })
              : row.key === 'memory' && split.memory
                ? split.memory.map(([path, tokens]) => `${path} ${formatTokens(tokens)}`).join(' · ')
                : ''
      const head = sourceRow(undefined, setupName(row.key), nameW - 2, formatTokens(row.tokens), undefined, 2)
      const room = width - lineWidth(head) - 2
      lines.push(extra !== '' && room >= 8 ? [...head, muted(`  ${fit(extra, room)}`)] : head)
    }
  }
  if (split.items.length > 0) {
    lines.push([muted(t(L, 'detail.context.largest'))])
    for (const item of split.items) {
      const what = item.tool ? [item.tool, item.what].filter(Boolean).join(' ') : item.note ? t(L, `ctx.note.${item.note}`) : t(L, `ctx.part.${item.kind ?? 'note'}`)
      const tokens = ` ~${formatTokens(item.tokens)}`
      lines.push([{ text: '  ' }, { text: '■', color: SOURCE_COLORS[item.source] }, { text: ` ${fit(what, Math.max(8, width - 4 - displayWidth(tokens)))}` }, muted(tokens)])
    }
  }
  return lines
}

/** After the chart: the tool schemas outside the window (never part of the bar), and how the split was measured. */
function contextAfterLines(r: Readings, width: number): Line[] {
  const L = r.ctx.locale
  const split = r.c.ctx
  if (!split || sourceTokens(split).length === 0) return []
  const lines: Line[] = []
  const deferred = split.deferred
  if (deferred && deferred.mcp + deferred.tools > 0) {
    const parts = [...(deferred.mcp > 0 ? [t(L, 'detail.context.deferredMcp', { tokens: formatTokens(deferred.mcp), n: deferred.mcpTools })] : []), ...(deferred.tools > 0 ? [t(L, 'detail.context.deferredTools', { tokens: formatTokens(deferred.tools) })] : [])]
    lines.push(...para(t(L, 'detail.context.deferred', { parts: parts.join(' · ') }), width))
  }
  lines.push(...wrapLine([muted(t(L, 'detail.context.how'))], width, 10))
  return lines
}

function contextDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c } = r
  const fill = contextNow(c)
  const share = contextShare(fill)
  const level: Level = share === undefined ? 'none' : share >= 90 ? 'bad' : share >= 70 ? 'warn' : 'none'
  const tone = toneOf(level)
  const title: Line = [{ text: formatPercent(fill.pct), bold: true, ...(tone ? { tone } : {}) }, ...(fill.tokens !== undefined && fill.window ? [muted(` · ${t(L, 'ctx.of', { tokens: formatTokens(fill.tokens), window: formatTokens(fill.window) })}`)] : [])]
  const lines: Line[] = []
  if (fill.autoCompact !== undefined) lines.push([{ text: t(L, 'detail.context.at', { at: formatTokens(fill.autoCompact), ...(fill.tokens !== undefined ? { left: formatTokens(Math.max(0, fill.autoCompact - fill.tokens)) } : { left: '—' }) }) }])
  else if (c.autoCompact && !c.autoCompact.isOn) lines.push(...para(t(L, 'detail.context.off'), width))
  lines.push(...contextSplitLines(r, width))
  // Turn by turn, as each ended: against the point it compacts at (or the window) once the turns come
  // near it, else scaled to the turns themselves, so a session far from it still shows its shape.
  const turns = c.history.filter(h => h.ctx !== undefined)
  if (turns.length > 0) {
    const values = turns.map(h => h.ctx ?? 0)
    const point = fill.autoCompact ?? fill.window
    const largest = Math.max(...values)
    const isNear = point === undefined || largest >= CHART_NEAR * point
    const max = isNear ? (point ?? largest) : largest
    const per = turns.length * 2 <= width - 6 ? 2 : 1
    // Colour still reads against the point: amber from 70% of the way, red from 90%.
    const limit = point ?? largest
    const toneAt = (v: number): Tone | undefined => (v >= 0.9 * limit ? 'bad' : v >= 0.7 * limit ? 'warn' : undefined)
    const chart = columnChart(values, max, 3, toneAt, per)
    // A compaction marks the turn it came in or before.
    const marks = turns
      .map((h, i) => ((c.compactTimes ?? []).some(at => at <= h.endedAt && at > (turns[i - 1]?.endedAt ?? 0)) ? '⟲' : ' '))
      .map(mark => mark.padEnd(per))
      .join('')
    const first = turns[0]?.n ?? 0
    const last = turns.at(-1)?.n ?? 0
    lines.push(...charted([...chart, ...(marks.trim() !== '' ? [[muted(marks)]] : [])], t(L, 'detail.context.turn', { n: first }), first === last ? '' : t(L, 'detail.context.turn', { n: last }), width))
    lines.push(...para(isNear || point === undefined ? t(L, 'detail.context.scale', { max: formatTokens(max) }) : t(L, 'detail.context.scaleTurns', { max: formatTokens(largest), point: formatTokens(point) }), width))
  } else lines.push(...para(t(L, 'detail.context.noTurns'), width))
  const times = (c.compactTimes ?? []).map(clockText)
  lines.push(...para(c.compactions === 0 ? t(L, 'detail.context.noCompaction') : t(L, c.compactions === 1 ? 'detail.context.compaction' : 'detail.context.compactions', { n: c.compactions, times: times.join(t(L, 'sep.items')) || '—' }), width))
  lines.push(...contextAfterLines(r, width))
  return { id: 'context', title, lines }
}

function costDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c } = r
  const priced = c.history.filter(h => h.costUsd !== undefined)
  const title: Line = [{ text: t(L, 'cost.session', { usd: formatUsd(c.reading?.costUsd) }), bold: true }]
  const lines: Line[] = [[muted(t(L, priced.length === 1 ? 'detail.cost.pricedOne' : 'detail.cost.priced', { n: priced.length }))]]
  const mid = median(c.turnUsd)
  lines.push(...para(mid !== undefined ? t(L, 'detail.cost.median', { usd: formatUsd(mid) }) : t(L, 'detail.cost.noMedian'), width))
  // The turns that cost most, most first: the ledger's figure where it priced them, else their tokens.
  const ranked = [...c.history].sort((a, b) => (b.costUsd ?? -1) - (a.costUsd ?? -1) || b.tokens - a.tokens).slice(0, 5)
  for (const h of ranked) {
    const amount = h.costUsd !== undefined ? formatUsd(h.costUsd) : formatTokens(h.tokens)
    const factor = mid !== undefined && mid > 0 && h.costUsd !== undefined ? `${(h.costUsd / mid).toFixed(1)}×` : ''
    const head = `#${h.n}`.padStart(4) + `  ${amount.padStart(7)}  ${factor.padStart(5)}  ${clockText(h.startedAt)}`
    const words = h.prompt ?? ''
    const room = width - displayWidth(head) - 2
    const tone: Tone | undefined = h.runaway ? 'warn' : undefined
    lines.push([{ text: head, ...(tone ? { tone } : {}) }, ...(words && room >= 8 ? [muted(`  ${fit(words, room)}`)] : [])])
  }
  if (ranked.length === 0) lines.push([muted(t(L, 'pane.history.none'))])
  const tokens = c.history.slice(-20).map(h => h.tokens)
  if (tokens.length > 1) lines.push([{ text: `  ${sparkline(tokens)}` }, muted(` ${t(L, 'detail.cost.spark', { n: tokens.length })}`)])
  return { id: 'cost', title, lines }
}

/** A run's verdict, its mark first: `✓ types+tests  175 passed · 9.1 s · 14:32 (2 min ago)`. */
function runLine(check: CheckResult, r: Readings): Line {
  const L = r.ctx.locale
  const mark = check.status === 'pass' ? '✓' : check.status === 'fail' ? '✗' : check.status === 'running' || check.status === 'background' ? '◌' : check.status === 'hidden' ? '?' : '–'
  const tone: Tone | undefined = check.status === 'pass' ? 'ok' : check.status === 'fail' ? 'bad' : undefined
  const when = check.replayed ? t(L, 'resume.before') : `${clockText(check.endedAt ?? check.startedAt)} (${formatAge(r.ctx.now - (check.endedAt ?? check.startedAt), L)})`
  const facts = [checkSummary(check, L), ...(check.durationMs !== undefined && check.status !== 'running' ? [formatDuration(check.durationMs)] : []), when]
  return [{ text: `${mark} `, ...(tone ? { tone } : {}) }, { text: kindsText(check, L), bold: true, ...(tone ? { tone } : {}) }, { text: `  ${facts.join(' · ')}` }]
}

function checksDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c } = r
  const runs = c.checks.filter(ch => ch.status !== 'running' || ch === c.checks.at(-1))
  const passed = runs.filter(ch => ch.status === 'pass').length
  const failed = runs.filter(ch => ch.status === 'fail').length
  const stopped = runs.filter(ch => ch.status === 'interrupted' || ch.status === 'hidden').length
  const title: Line = [{ text: t(L, runs.length === 1 ? 'detail.checks.run' : 'detail.checks.runs', { n: runs.length }), bold: true }]
  if (runs.length === 0) return { id: 'checks', title: [muted('—')], lines: [[muted(t(L, 'checks.none'))]] }
  const lines: Line[] = [[muted([t(L, 'checks.passed', { n: passed }), t(L, 'checks.failed', { n: failed }), ...(stopped > 0 ? [t(L, 'detail.checks.stopped', { n: stopped })] : [])].join(t(L, 'sep.clause')))]]
  const open = unverified(c)
  lines.push(...para(open === undefined ? t(L, 'ho.noPass') : open.count === 0 ? t(L, 'detail.checks.noneSince') : t(L, open.count === 1 ? 'detail.checks.editSince' : 'detail.checks.editsSince', { n: open.count }), width))
  const failing = c.failures.map(f => t(L, `kind.${f.kind}`))
  if (failing.length > 0) lines.push([{ text: t(L, 'detail.checks.failing', { kinds: failing.join(t(L, 'sep.items')) }), tone: 'bad' }])
  const shown = [...runs].reverse().slice(0, 5)
  for (const check of shown) {
    lines.push(runLine(check, r))
    lines.push([muted(`  ${fit(check.command, width - 2)}`)])
    // What failed, in the run's own words: its first failing lines.
    if (check.status === 'fail' && check.tail) for (const text of check.tail.split('\n').slice(0, 3)) lines.push([muted('  │ '), { text: fit(text, width - 4), tone: 'bad' }])
  }
  if (runs.length > shown.length) lines.push([muted(t(L, 'detail.checks.earlier', { n: runs.length - shown.length }))])
  // Kinds a chain ran together are one run of each.
  if (runs.some(ch => kindsOf(ch).length > 1 && judgedKinds(ch).length !== kindsOf(ch).length)) lines.push(...para(t(L, 'detail.checks.named'), width))
  return { id: 'checks', title, lines }
}

function filesDetail(r: Readings, width: number, extra: DetailExtra): Detail {
  const L = r.ctx.locale
  const { c } = r
  const edits = c.files.reduce((sum, f) => sum + f.edits, 0)
  if (c.files.length === 0) return { id: 'files', title: [muted('—')], lines: [[muted(t(L, 'files.none'))]] }
  const title: Line = [{ text: t(L, 'files.count', { files: t(L, c.files.length === 1 ? 'unit.file' : 'unit.files', { n: c.files.length }), edits: t(L, edits === 1 ? 'unit.edit' : 'unit.edits', { n: edits }) }), bold: true }]
  const open = unverified(c)
  const unseen = new Set(open?.paths ?? [])
  const lines: Line[] = para(open === undefined ? t(L, 'ho.noPass') : unseen.size === 0 ? t(L, 'ho.noUnverified') : t(L, 'detail.files.unverified', { n: unseen.size }), width)
  const files = [...c.files].sort((a, b) => b.edits - a.edits || b.lastAt - a.lastAt)
  const root = extra.root ?? c.meta.root
  const shown = files.slice(0, 10)
  for (const f of shown) {
    const marks = [...(f.created ? [t(L, 'detail.files.new')] : []), ...(unseen.has(f.path) ? [t(L, 'detail.files.unseen')] : [])]
    const tail = marks.length > 0 ? `  ${marks.join(' · ')}` : ''
    const count = `×${f.edits}`.padStart(4)
    const path = relativePath(f.path, root)
    const room = width - displayWidth(count) - 2 - displayWidth(tail)
    lines.push([{ text: count }, { text: `  ${displayWidth(path) <= room ? path : `…${path.slice(-(Math.max(4, room) - 1))}`}` }, muted(tail)])
  }
  if (files.length > shown.length) lines.push([muted(t(L, 'time.more', { n: files.length - shown.length }))])
  return { id: 'files', title, lines }
}

function agentsDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const { c, ctx, work } = r
  const isOpen = (a: AgentRun) => a.status === 'running' || a.status === 'background'
  const isAlive = (a: AgentRun) => isOpen(a) || a.status === 'idle' || a.status === 'waiting'
  const done = c.agents.filter(a => a.status === 'done').length
  const failed = c.agents.filter(a => a.status === 'failed').length
  if (c.agents.length === 0) return { id: 'agents', title: [muted('—')], lines: [[muted(t(L, 'agents.none'))]] }
  const title: Line = [{ text: t(L, c.agents.length === 1 ? 'detail.agents.run' : 'detail.agents.runs', { n: c.agents.length }), bold: true }]
  // Running is Claude's agents at work, as the progress counts them; idle teammates and waiting agents are alive, not running.
  const quiet = [...(work.idle.length > 0 ? [t(L, work.idle.length === 1 ? 'work.idleOne' : 'work.idle', { n: work.idle.length })] : []), ...(work.waiting.length > 0 ? [t(L, 'work.waiting', { n: work.waiting.length })] : [])]
  const lines: Line[] = [[muted([t(L, 'agents.running', { n: work.agents.length }), ...quiet, t(L, 'agents.done', { n: done }), ...(failed > 0 ? [t(L, 'agents.failedCount', { n: failed })] : [])].join(' · '))]]
  for (const a of [...c.agents].sort((x, y) => y.startedAt - x.startedAt).slice(0, 8)) {
    const name = `${a.type === 'general-purpose' ? 'general' : a.type} · ${a.description}`
    const length = isAlive(a) ? `${hm(ctx.now - a.startedAt)}…` : a.replayed ? t(L, 'resume.before') : formatSpan(a.durationMs ?? (a.endedAt ?? ctx.now) - a.startedAt)
    const facts: string[] = []
    if (a.status === 'failed') facts.push(t(L, 'agents.failed'))
    else if (a.status === 'remote') facts.push(t(L, 'agents.remote'))
    else if (a.status === 'idle') facts.push(t(L, a.teammate ? 'detail.agents.teammateIdle' : 'agents.idle'))
    else if (a.status === 'waiting') facts.push(t(L, 'agents.waiting'))
    else if (a.teammate && isOpen(a)) facts.push(t(L, 'agents.teammate'))
    else if (a.isBackground) facts.push(t(L, 'agents.background'))
    else if (a.tokens !== undefined) facts.push(t(L, 'detail.agents.tokens', { tokens: formatTokens(a.tokens) }))
    if (a.toolUses !== undefined) facts.push(t(L, a.toolUses === 1 ? 'unit.tool' : 'unit.tools', { n: a.toolUses }))
    if (a.added !== undefined || a.removed !== undefined) facts.push(`+${a.added ?? 0} −${a.removed ?? 0}`)
    const mark: Span = a.status === 'failed' ? { text: '✗ ', tone: 'bad' } : isOpen(a) ? { text: '▸ ', bold: true } : a.status === 'idle' || a.status === 'waiting' ? muted('○ ') : a.status === 'remote' ? muted('↗ ') : muted('✓ ')
    const tail = `  ${length}${facts.length > 0 ? ` · ${facts.join(' · ')}` : ''}`
    lines.push([mark, { text: fit(name, Math.max(8, width - 2 - displayWidth(tail))), ...(a.status === 'failed' ? { tone: 'bad' as const } : {}) }, muted(tail)])
  }
  if (c.agents.length > 8) lines.push([muted(t(L, 'time.more', { n: c.agents.length - 8 }))])
  return { id: 'agents', title, lines }
}

function sessionDetail(r: Readings, width: number, extra: DetailExtra): Detail {
  const L = r.ctx.locale
  const { c, ctx } = r
  const meta = c.meta
  const model = modelOf(c)
  const title: Line = [{ text: [model, meta.effort].filter(Boolean).join(' · ') || '—', bold: true }]
  // 9 columns, or the longest head and two more where a language's words are longer (`プロジェクト` takes 12).
  const headW = Math.max(9, ...(['detail.session.model', 'detail.session.effort', 'detail.session.up', 'detail.session.project'] as const).map(key => displayWidth(t(L, key)) + 2))
  const head = (key: Parameters<typeof t>[1]) => ({ text: pad(t(L, key), headW), bold: true, tone: 'muted' as const })
  const lines: Line[] = []
  const raw = meta.model ?? c.lastStep?.model
  lines.push([head('detail.session.model'), { text: model ?? '—' }, ...(raw && raw !== model ? [muted(` (${raw})`)] : [])])
  lines.push([head('detail.session.effort'), { text: meta.effort ?? '—' }, muted(` · ${t(L, 'detail.session.mode')} `), { text: meta.mode ?? '—' }])
  const began = c.sessionStartedAt ?? c.startedAt
  const working = c.activeMs + (c.turn ? Math.max(0, ctx.now - c.turn.startedAt) : 0)
  const turns = c.turnCount + (c.turn ? 1 : 0)
  lines.push([head('detail.session.up'), { text: hm(ctx.now - began) }, muted(` · ${t(L, 'detail.session.since', { time: clockText(began) })} · ${t(L, 'time.working', { time: hm(working) })} · ${t(L, turns === 1 ? 'ho.turns.one' : 'ho.turns.many', { n: turns })}`)])
  if (c.joinedLate) lines.push(...wrapLine([muted(t(L, 'detail.session.joined', { time: clockText(c.startedAt) }))], width - headW, 2).map(line => [{ text: ' '.repeat(headW) }, ...line]))
  const root = extra.root ?? meta.root
  if (root) lines.push([head('detail.session.project'), { text: meta.repo ?? baseName(root) }, muted(`  ${fit(root, Math.max(8, width - headW - 2 - displayWidth(meta.repo ?? baseName(root))))}`)])
  return { id: 'session', title, lines }
}

function healthDetail(r: Readings, width: number): Detail {
  const L = r.ctx.locale
  const h = r.health
  const tone = toneOf(h.level)
  const title: Line = [{ text: `${h.score} ${wordText(h.word, L)}`, bold: true, ...(tone ? { tone } : {}) }]
  const lines: Line[] = [...para(t(L, 'detail.health.how'), width)]
  const nameW = Math.max(...h.parts.map(p => displayWidth(partName(p.id, L)))) + 2
  const offs = h.parts.map(p => `${p.off > 0 ? `−${p.off}` : '0'} / ${p.weight}`)
  const offW = Math.max(...offs.map(displayWidth))
  const values = h.parts.map(p => partValue(p, L, clockText))
  const room = width - nameW - offW - 2
  // One form for every part: each value beside its name where all of them fit, else each under its name.
  const isBeside = values.every(value => displayWidth(value) <= room)
  h.parts.forEach((p, i) => {
    const off: Span = { text: `  ${(offs[i] ?? '').padStart(offW)}`, ...(p.off === 0 ? { tone: 'muted' as const } : {}) }
    const value: Span = { text: values[i] ?? '', ...(p.reading ? {} : { tone: 'muted' as const }) }
    const name: Span = { text: partName(p.id, L), bold: true }
    if (isBeside) lines.push([{ ...name, text: pad(name.text, nameW) }, { ...value, text: pad(value.text, room) }, off])
    else {
      lines.push([{ ...name, text: pad(name.text, width - offW - 2) }, off])
      lines.push(...wrapLine([value], width - 2, 2).map(line => [{ text: '  ' }, ...line]))
    }
    const indent = isBeside ? nameW : 2
    lines.push(...wrapLine([muted(partRule(p.id, L))], width - indent, 2).map(line => [{ text: ' '.repeat(indent) }, ...line]))
  })
  lines.push([muted(t(L, 'detail.health.sum', { score: h.score, off: 100 - h.score }))])
  return { id: 'health', title, lines }
}

files.src/panes.ts:
// The pane `/quackpit` opens, a view at a time (views.ts): on top the view
// bar and, outside the overview, the progress in one line; at the bottom the
// keys of the view in front; between them the view's body, sized to the rows
// the pane has. The overview is progress across the top and the instruments
// under it (instruments.ts), with one line of cautions when there are any; a
// press on an instrument drills into its detail (details.ts), in its place
// or, where the pane is wide, beside a list of the instruments. The other
// views are the timeline (timeline.ts), the turns with the mission over them,
// the band's layout, the handover and the guide. Everything is laid out as
// parts of a known height, so the terminal's pinned window (pin.ts) can tell
// where each press is. Host-neutral; the adapter draws them. Pure.

import { cautionsOf, cautionText, type Caution } from './duck'
import type { Level } from './derive'
import type { Detail, DetailId } from './details'
import { baseName, clockText, formatDuration, formatPercent, formatTokens, formatUsd } from './format'
import { t, type Key, type Locale } from './i18n'
import { DETAIL_OF, INSTRUMENT_MIN_WIDTH, INSTRUMENT_ROWS, instrumentIds, instrumentName, instrumentOf, instrumentReading, nameColumn, shortName, type Instrument, type InstrumentId, type InstrumentSize } from './instruments'
import { contextNow, turnLength, type TurnSource } from './model'
import { displayWidth, fit, fitLine, lineWidth, pad, plain, sparkline, wrapLine, type Line, type Span, type Tone } from './text'
import { summaryLine, topSection, type Summary, type TopSection } from './top'
import { weakestHint, wordText } from './health'
import { backgroundCheckText, checksFace, checkWhen, compactFace, contextFace, costFace, kindsText, shownCheck, tileFace, type Readings, type TileId } from './tiles'
import type { Graphic } from './gauges'
import type { TimeBlocks } from './timeline'
import type { GuideRow } from './guide'
import { barWidth, hintLine, viewBar, type PaneView, type ViewBar } from './views'

const toneOf = (level: Level): Tone | undefined => (level === 'bad' ? 'bad' : level === 'warn' ? 'warn' : level === 'ok' ? 'ok' : undefined)
const muted = (text: string): Span => ({ text, tone: 'muted' })

// ------------------------------------------------------------------ the cautions and the mission

/**
 * The cautions as one line, only when there are any: `Quack:` and each one's
 * words, the acknowledged ones dim. The overview's; the band says the same.
 */
export function cautionsLine(r: Readings, width: number): Line | undefined {
  const L = r.ctx.locale
  const list: Caution[] = cautionsOf(r.c, r.ctx.now)
  if (list.length === 0) return undefined
  const worst = list.some(k => k.level === 'bad' && !r.c.ack.includes(k.key)) ? 'bad' : 'warn'
  const spans: Span[] = [{ text: `${t(L, 'duck.quack')} `, bold: true, tone: list.every(k => r.c.ack.includes(k.key)) ? 'muted' : worst }]
  list.forEach((k, i) => {
    const isAck = r.c.ack.includes(k.key)
    if (i > 0) spans.push(muted(' · '))
    spans.push({ text: cautionText(k, L), ...(isAck ? { tone: 'muted' as const } : { tone: k.level === 'bad' ? ('bad' as const) : ('warn' as const) }) })
  })
  return fitLine(spans, width)
}

/** A head of 9 columns, then words that wrap beneath it, at most two lines. */
function headed(head: string, body: Line, width: number): Line[] {
  // 9 columns, or the head and two more where a language's word is longer (`ミッション` takes 10).
  const headW = Math.max(9, displayWidth(head) + 2)
  const lines = wrapLine(body, Math.max(8, width - headW), 2)
  return lines.map((line, i) => [i === 0 ? { text: pad(head, headW), bold: true, tone: 'muted' } : { text: ' '.repeat(headW) }, ...line])
}

/** The mission: the goal over two lines at most, cut where the second ends (the handover keeps it whole). */
export function missionLines(r: Readings, width: number): Line[] {
  const L = r.ctx.locale
  const goal = r.c.goal
  return headed(t(L, 'pane.mission'), [goal ? { text: goal } : muted(t(L, r.c.goalLost ? 'pane.goalLost' : 'pane.noGoal'))], width)
}

// ------------------------------------------------------------------ the turns

/** The turns table's columns: each head's words and its width. */
const HISTORY_COLUMNS: readonly [Key, number][] = [
  ['hist.n', 3],
  ['hist.start', 6],
  ['hist.time', 8],
  ['hist.tokens', 8],
  ['hist.cost', 7],
  ['hist.tools', 6],
  ['hist.edits', 6],
]

/** `text` padded on the left to `width` columns, a wide character counting two. */
const padStart = (text: string, width: number) => ' '.repeat(Math.max(0, width - displayWidth(text))) + text

/** A history row, and the transcript row it scrolls to when pressed: the turn's first tool call. */
export type HistoryRow = { line: Line; target?: string; n: number }

/**
 * What started a turn no person typed, in plain words: `(a subagent's report)`,
 * `(background task: Map the parser)`. Within `room` columns the name is cut,
 * never the words around it.
 */
export function sourceText(source: TurnSource, L: Locale, room = Infinity): string {
  const label = (name: string | undefined) => sourceLabel({ ...source, ...(name !== undefined ? { name } : {}) }, L)
  if (displayWidth(label(source.name)) <= room) return label(source.name)
  if (source.name === undefined) return fit(label(undefined), room)
  // The label's own words, measured with a one-column name (an empty one reads as no name at all).
  const around = displayWidth(label('x')) - 1
  return around + 2 <= room ? label(fit(source.name, room - around)) : fit(label(source.name), room)
}

function sourceLabel(source: TurnSource, L: Locale): string {
  const name = source.name
  switch (source.kind) {
    case 'report':
      return t(L, 'source.report')
    case 'task':
      return name ? t(L, 'source.taskNamed', { name }) : t(L, 'source.task')
    case 'teammate':
      return name ? t(L, 'source.teammateNamed', { name }) : t(L, 'source.teammate')
    case 'peer':
      return t(L, 'source.peer')
    case 'event':
      return t(L, 'source.event')
    case 'command':
      return name ? t(L, 'source.commandNamed', { name }) : t(L, 'source.command')
    case 'compaction':
      return t(L, 'source.compaction')
    case 'plugin':
      return name ? t(L, 'source.pluginNamed', { name }) : t(L, 'source.plugin')
    case 'system':
      return t(L, 'source.system')
  }
}

/** The last 20 turns as table rows, newest first. */
export function historyRows(r: Readings, width = 100): { head?: Line; rows: HistoryRow[] } {
  const L = r.ctx.locale
  const rows = r.c.history.slice(-20).reverse()
  if (rows.length === 0) return { rows: [{ n: 0, line: [muted(r.c.joinedLate ? t(L, 'pane.history.since', { time: clockText(r.c.startedAt) }) : t(L, 'pane.history.none'))] }] }
  // Each head over its column, aligned as the figures are: to the right, by display width.
  const head = HISTORY_COLUMNS.map(([key, w]) => padStart(t(L, key), w)).join(' ')
  return {
    head: [muted(head)],
    rows: rows.map((h): HistoryRow => {
      const tone: Tone | undefined = h.runaway ? 'warn' : h.aborted ? 'muted' : undefined
      const cells = [
        String(h.n).padStart(3),
        clockText(h.startedAt).padStart(6),
        formatDuration(turnLength(h)).padStart(8),
        formatTokens(h.tokens).padStart(8),
        formatUsd(h.costUsd).padStart(7),
        String(h.tools).padStart(6),
        String(h.edits).padStart(6),
      ]
      const row = cells.join(' ')
      // The prompt's words take what the pane has left, and none when that is too little to read;
      // a turn no person typed says what started it, never its markup.
      const room = Math.min(40, width - displayWidth(row) - 2)
      const words = h.prompt ? fit(h.prompt, room) : h.source ? sourceText(h.source, L, room) : undefined
      const line: Line = [{ text: row, ...(tone ? { tone } : {}) }, ...(words && room >= 8 ? [muted(`  ${words}`)] : [])]
      return { n: h.n, line, ...(h.firstTool ? { target: h.firstTool } : {}) }
    }),
  }
}

/** The longest run of the check history strip. */
const STRIP_RUNS = 24

/**
 * Every finished check as one square, newest on the right: ■ green for a
 * pass, ■ red for a failure, □ for a run that was stopped or whose result
 * was cut away. Nothing else is coloured.
 */
export function historyStrip(c: Readings['c']): Line {
  const runs = c.checks.filter(ch => ch.status === 'pass' || ch.status === 'fail' || ch.status === 'interrupted' || ch.status === 'hidden').slice(-STRIP_RUNS)
  return runs.map((ch): Span => (ch.status === 'interrupted' || ch.status === 'hidden' ? muted('□') : { text: '■', tone: ch.status === 'pass' ? 'ok' : 'bad' }))
}

// ------------------------------------------------------------------ the compact cells

/**
 * A compact cell, for a pane too short for the instruments: a title that is
 * its press, a gauge beside two lines; what an older build drew in its grid.
 */
export type Cell = { id: InstrumentId; title: string; graphic?: Graphic; lines: [Line, Line]; level: Level }

const fitTo = (line: Line, width: number): Line => fitLine(line, Math.max(1, width))

/**
 * Items joined with ` · ` over at most `max` lines of `width` columns, each
 * whole where it fits a line, the ones left over counted as `+N` at the end.
 */
export function packed(items: readonly string[], width: number, max: number): string[] {
  const lines: string[][] = [[]]
  const widthOf = (parts: readonly string[]) => displayWidth(parts.join(' · '))
  let i = 0
  for (; i < items.length; i++) {
    const item = fit(items[i] ?? '', width)
    const current = lines.at(-1) as string[]
    if (current.length === 0 || widthOf([...current, item]) <= width) current.push(item)
    else if (lines.length < max) lines.push([item])
    else break
  }
  let left = items.length - i
  const last = lines.at(-1) as string[]
  // The count of those left takes the last line's end, an item giving way to it where it must.
  while (left > 0 && last.length > 1 && widthOf(last) + ` +${left}`.length > width) {
    last.pop()
    left++
  }
  return lines.filter(parts => parts.length > 0).map(parts => parts.join(' · ') + (parts === last && left > 0 && widthOf(parts) + ` +${left}`.length <= width ? ` +${left}` : ''))
}

/** The tile a compact cell shows: the dials' own tiles. */
const TILE_OF: Readonly<Record<InstrumentId, TileId>> = { pace: 'pace', five: 'limits', context: 'context', cost: 'cost', checks: 'checks', files: 'files', health: 'health', session: 'session', agents: 'agents' }

/** A compact cell `width` columns wide. */
export function cellOf(r: Readings, id: InstrumentId, width: number): Cell {
  const { c, ctx } = r
  const L = ctx.locale
  const title = instrumentName(id, L)
  const textW = (chrome: number) => Math.max(8, width - chrome)
  switch (id) {
    case 'context': {
      const face = contextFace(r)
      const fill = contextNow(c)
      const tone = toneOf(face.level)
      const w = textW((face.graphic?.cols ?? 0) + 1)
      const line1: Line = [{ text: formatPercent(fill.pct), bold: true, ...(tone ? { tone } : {}) }]
      if (fill.tokens !== undefined && fill.window) line1.push(muted(` · ${t(L, 'ctx.of', { tokens: formatTokens(fill.tokens), window: formatTokens(fill.window) })}`))
      const left = { left: formatTokens(Math.max(0, fill.autoCompact !== undefined && fill.tokens !== undefined ? fill.autoCompact - fill.tokens : 0)) }
      const line2: Line =
        fill.autoCompact !== undefined && fill.tokens !== undefined
          ? [muted(displayWidth(t(L, 'cell.toCompact', left)) <= w ? t(L, 'cell.toCompact', left) : t(L, 'ctx.toCompact', left))]
          : c.autoCompact && !c.autoCompact.isOn
            ? [muted(t(L, 'ctx.compactOff'))]
            : fill.pct === undefined
              ? [muted(t(L, 'cell.noReading'))]
              : []
      // The compactions where they fit beside it; the detail lists them.
      const compacted = muted(` · ${t(L, 'ctx.compactions', { n: c.compactions })}`)
      if (c.compactions > 0 && lineWidth([...line2, compacted]) <= w) line2.push(compacted)
      return { id, title, ...(face.graphic ? { graphic: face.graphic } : {}), lines: [fitTo(line1, w), fitTo(line2, w)], level: face.level }
    }
    case 'checks': {
      const face = checksFace(r)
      const check = shownCheck(c)
      if (!check) return { id, title, lines: [[muted('—')], [muted(t(L, 'checks.none'))]], level: 'none' }
      const strip = historyStrip(c).slice(-Math.max(4, Math.min(12, width - 18)))
      // A check in the background: its time so far and its command's usual length, where the cell has room.
      const background = backgroundCheckText(r, check, width - 2)
      const line1: Line = background ? [{ text: `◌ ${background}`, bold: true }] : face.lines[0]
      const line2: Line = background ? [...strip, muted(`  ${plain(face.lines[1])}`)] : [...strip, muted(`  ${kindsText(check, L)} · ${checkWhen(r, check)}`)]
      return { id, title, lines: [fitTo(line1, width), fitTo(line2, width)], level: face.level }
    }
    case 'cost': {
      const face = costFace(r)
      const values = c.history.slice(-12).map(h => h.tokens)
      const line2: Line = values.length > 0 ? [{ text: sparkline(values) }, muted(` ${t(L, 'cost.spark')}`)] : c.turn ? [] : [muted(t(L, 'pane.history.none'))]
      return { id, title, lines: [fitTo(face.lines[0], width), fitTo(line2, width)], level: face.level }
    }
    case 'files': {
      const face = tileFace(r, 'files')
      if (c.files.length === 0) return { id, title, lines: [[muted('—')], [muted(t(L, 'files.none'))]], level: 'none' }
      // The files edited most, each name whole where it fits, the rest counted.
      const files = [...c.files].sort((a, b) => b.edits - a.edits || b.lastAt - a.lastAt)
      const [first = ''] = packed(files.map(f => `${baseName(f.path)} ×${f.edits}`), width, 1)
      return { id, title, lines: [fitTo(face.lines[0], width), [muted(first)]], level: 'none' }
    }
    case 'health': {
      const h = r.health
      const tone = toneOf(h.level)
      const line1: Line = h.isMeasuring ? [{ text: `${h.score} ${wordText(h.word, L)}`, bold: true, ...(tone ? { tone } : {}) }] : [muted('—')]
      return { id, title, lines: [fitTo(line1, width), [muted(fit(weakestHint(h, L), width))]], level: h.level }
    }
    case 'pace':
    case 'five': {
      // The dials' compact faces: the band's own, its one-row tachometer and its limits without their meters.
      const face = compactFace(r, TILE_OF[id])
      return { id, title, lines: [fitTo(face.lines[0], width), fitTo(face.lines[1], width)], level: face.level }
    }
    default: {
      const face = tileFace(r, TILE_OF[id])
      const w = textW(face.graphic ? face.graphic.cols + 1 : 0)
      return { id, title, ...(face.graphic ? { graphic: face.graphic } : {}), lines: [fitTo(face.lines[0], w), fitTo(face.lines[1], w)], level: face.level }
    }
  }
}

// ------------------------------------------------------------------ the overview, sized

/** How the overview draws its instruments: full, small, compact cells, or a line each. */
export type OverviewForm = InstrumentSize | 'compact' | 'lines'

/** The overview's plan for a pane: progress whole or as a line, the instruments' form, how many across, whether the bar has its rule. */
export type OverviewPlan = { top: 'full' | 'line'; form: OverviewForm; across: 1 | 2; cellWidth: number; rule: boolean; gap: boolean }

/** The gutter between two cells side by side: a space, a thin rule, a space. */
export const GUTTER = 3

/** The fewest rows a pane gives before the view bar drops its rule (an inline pane's twelve). */
const RULE_FROM_ROWS = 20

/** The narrowest compact cell, and the narrowest line two of them share. */
const COMPACT_MIN_WIDTH = 24
const LINES_TWO_FROM = 70

function across(form: OverviewForm, width: number): 1 | 2 {
  const twoW = Math.floor((width - GUTTER) / 2)
  if (form === 'full' || form === 'small') return 2
  if (form === 'compact') return twoW >= COMPACT_MIN_WIDTH ? 2 : 1
  return width >= LINES_TWO_FROM ? 2 : 1
}

/** Rows the instruments take in a form: a title and its rows each, a rule between the rows of cells; a line each, no rules. */
export function instrumentRows(form: OverviewForm, count: number, n: 1 | 2): number {
  const rows = Math.ceil(count / n)
  if (form === 'lines') return rows
  const each = form === 'compact' ? 3 : 1 + INSTRUMENT_ROWS[form]
  return rows * each + Math.max(0, rows - 1)
}

/**
 * The overview's plan for `width` columns and `paneRows` rows: the largest
 * form that fits, progress kept whole before the instruments stay large
 * (it is what a person opening the pane mid-task wants first). Full
 * instruments need two cells of 33 columns, small ones two of 26; past
 * that, compact cells, then a line each. Where nothing fits, the smallest,
 * and the body scrolls under the pinned bar.
 */
export function overviewPlan(r: Readings, width: number, paneRows: number): OverviewPlan {
  const count = instrumentIds(r).length
  const top = topSection(r, width)
  const topRows = (top.head.length > 0 ? 1 : 0) + (top.pond ? 2 : 0) + top.under.length
  const cautions = cautionsOf(r.c, r.ctx.now).length > 0 ? 1 : 0
  const rule = paneRows >= RULE_FROM_ROWS
  const head = 1 + (rule ? 1 : 0)
  const foot = 1
  const twoW = Math.floor((width - GUTTER) / 2)
  const isWide = (form: OverviewForm) => (form === 'full' || form === 'small' ? twoW >= INSTRUMENT_MIN_WIDTH[form] : true)
  // The instruments stay instruments as long as they can, progress giving way to a line first; then compact cells, then a line each.
  const order: { top: 'full' | 'line'; form: OverviewForm }[] = [
    { top: 'full' as const, form: 'full' as const },
    { top: 'full' as const, form: 'small' as const },
    { top: 'line' as const, form: 'full' as const },
    { top: 'line' as const, form: 'small' as const },
    { top: 'full' as const, form: 'compact' as const },
    { top: 'line' as const, form: 'compact' as const },
    { top: 'full' as const, form: 'lines' as const },
    { top: 'line' as const, form: 'lines' as const },
  ].filter(c => isWide(c.form))
  const total = (c: { top: 'full' | 'line'; form: OverviewForm }, gap: boolean) => head + foot + (c.top === 'full' ? topRows : 1) + (gap ? 1 : 0) + instrumentRows(c.form, count, across(c.form, width)) + cautions
  for (const c of order) {
    const n = across(c.form, width)
    const cellWidth = n === 2 ? twoW : width
    if (total(c, true) <= paneRows) return { ...c, across: n, cellWidth, rule, gap: true }
    if (total(c, false) <= paneRows) return { ...c, across: n, cellWidth, rule, gap: false }
  }
  const last = order.at(-1) ?? { top: 'line', form: 'lines' }
  const n = across(last.form, width)
  return { ...last, across: n, cellWidth: n === 2 ? twoW : width, rule, gap: false }
}

// ------------------------------------------------------------------ the parts of a body

/** One instrument as a line: its press's name and its reading. */
export type ReadingItem = { id: InstrumentId; detail: DetailId; name: string; reading: Line }

export type BodyPart =
  | { kind: 'top'; top: TopSection }
  | { kind: 'summary'; summary: Summary }
  | { kind: 'blank' }
  | { kind: 'instruments'; size: InstrumentSize; across: 1 | 2; cellWidth: number; rows: Instrument[][] }
  | { kind: 'cells'; across: 1 | 2; cellWidth: number; rows: Cell[][] }
  | { kind: 'readings'; across: 1 | 2; cellWidth: number; nameWidth: number; items: ReadingItem[]; open?: DetailId }
  | { kind: 'cautions'; line: Line }
  | { kind: 'lines'; lines: Line[] }
  /** The press that leaves a detail (`b`), with the detail's name and headline beside it. */
  | { kind: 'back'; label: string; name: string; title: Line }
  /** An open detail beside the list of instruments. */
  | { kind: 'beside'; left: BodyPart[]; right: BodyPart[]; leftWidth: number }
  | { kind: 'turns'; rows: HistoryRow[] }
  | { kind: 'presses'; rows: Press[][] }

/** A press of the band's layout or the handover's, laid out in rows by its width. */
export type Press = { key: string; label: string; width: number; kind: 'remove' | 'add' | 'reset' | 'write' | 'copy'; tile?: TileId; isPrimary?: boolean }

/** How many rows a part draws. */
export function partRows(p: BodyPart): number {
  switch (p.kind) {
    case 'top':
      return (p.top.head.length > 0 ? 1 : 0) + (p.top.pond ? 2 : 0) + p.top.under.length
    case 'summary':
    case 'blank':
    case 'cautions':
    case 'back':
      return 1
    case 'instruments':
      return p.rows.length * (1 + INSTRUMENT_ROWS[p.size]) + Math.max(0, p.rows.length - 1)
    case 'cells':
      return p.rows.length * 3 + Math.max(0, p.rows.length - 1)
    case 'readings':
      return Math.ceil(p.items.length / p.across)
    case 'lines':
      return p.lines.length
    case 'beside':
      return Math.max(sumRows(p.left), sumRows(p.right))
    case 'turns':
      return p.rows.length
    case 'presses':
      return p.rows.length
  }
}

export function sumRows(parts: readonly BodyPart[]): number {
  return parts.reduce((sum, p) => sum + partRows(p), 0)
}

/** The presses a part draws, each with the row it stands on within the part and its height. */
export function partKeys(p: BodyPart): { key: string; at: number; height: number }[] {
  switch (p.kind) {
    case 'instruments':
      return p.rows.flatMap((row, i) => row.map(cell => ({ key: `cell-${cell.detail}`, at: i * (2 + INSTRUMENT_ROWS[p.size]), height: 1 })))
    case 'cells':
      return p.rows.flatMap((row, i) => row.map(cell => ({ key: `cell-${DETAIL_OF[cell.id]}`, at: i * 4, height: 1 })))
    case 'readings':
      return p.items.map((item, k) => ({ key: `cell-${item.detail}`, at: Math.floor(k / p.across), height: 1 }))
    case 'back':
      return [{ key: 'pane-back', at: 0, height: 1 }]
    case 'beside': {
      const keys = (parts: readonly BodyPart[]) => {
        let at = 0
        return parts.flatMap(part => {
          const out = partKeys(part).map(k => ({ ...k, at: k.at + at }))
          at += partRows(part)
          return out
        })
      }
      return [...keys(p.left), ...keys(p.right)]
    }
    case 'turns':
      return p.rows.flatMap((row, i) => (row.target ? [{ key: `pane-turn-${row.n}`, at: i, height: 1 }] : []))
    case 'presses':
      return p.rows.flatMap((row, i) => row.map(press => ({ key: press.key, at: i, height: 1 })))
    default:
      return []
  }
}

/** Every press of a body, with the row of the body it stands on. */
export function bodyKeys(parts: readonly BodyPart[]): Map<string, { at: number; height: number }> {
  const out = new Map<string, { at: number; height: number }>()
  let at = 0
  for (const p of parts) {
    for (const k of partKeys(p)) out.set(k.key, { at: at + k.at, height: k.height })
    at += partRows(p)
  }
  return out
}

/** Rows of `width` columns, cells `across` to a row. */
function inRows<T>(items: readonly T[], n: number): T[][] {
  const rows: T[][] = []
  for (let i = 0; i < items.length; i += n) rows.push(items.slice(i, i + n))
  return rows
}

/** The instruments as one line each, `across` to a row, names in a column. */
export function readingsPart(r: Readings, width: number, n: 1 | 2, open?: DetailId): Extract<BodyPart, { kind: 'readings' }> {
  const ids = instrumentIds(r)
  const cellWidth = n === 2 ? Math.floor((width - GUTTER) / 2) : width
  const nameWidth = nameColumn(r, ids)
  const items = ids.map((id): ReadingItem => ({ id, detail: instrumentOf(r, id, cellWidth, 'small').detail, name: shortName(id, r.ctx.locale), reading: fitLine(instrumentReading(r, id), Math.max(4, cellWidth - nameWidth - 2)) }))
  return { kind: 'readings', across: n, cellWidth, nameWidth, items, ...(open ? { open } : {}) }
}

/** The overview's body as its plan has it: progress, the instruments, the cautions. */
export function overviewBody(r: Readings, width: number, plan: OverviewPlan): BodyPart[] {
  const parts: BodyPart[] = []
  parts.push(plan.top === 'full' ? { kind: 'top', top: topSection(r, width) } : { kind: 'summary', summary: summaryLine(r, width) })
  if (plan.gap) parts.push({ kind: 'blank' })
  const ids = instrumentIds(r)
  if (plan.form === 'full' || plan.form === 'small') {
    const size = plan.form
    const widths = (j: number) => (plan.across === 2 ? (j === 0 ? plan.cellWidth : width - plan.cellWidth - GUTTER) : width)
    const rows = inRows(ids, plan.across).map(row => row.map((id, j) => instrumentOf(r, id, widths(j), size)))
    parts.push({ kind: 'instruments', size, across: plan.across, cellWidth: plan.cellWidth, rows })
  } else if (plan.form === 'compact') {
    parts.push({ kind: 'cells', across: plan.across, cellWidth: plan.cellWidth, rows: inRows(ids.map(id => cellOf(r, id, plan.cellWidth)), plan.across) })
  } else {
    parts.push(readingsPart(r, width, plan.across))
  }
  const cautions = cautionsLine(r, width)
  if (cautions) parts.push({ kind: 'cautions', line: cautions })
  return parts
}

/** Where an open detail goes beside the list of instruments: from 90 columns, which leaves it 56. */
export const BESIDE_FROM = 90
/** The list beside an open detail. */
const BESIDE_LIST = 31

/**
 * An open detail: in the overview's place, under its back press, or beside
 * the list of instruments where the pane is wide, the open one marked.
 */
export function drillBody(r: Readings, width: number, open: { name: string; detail: Detail }, back: string, besideDetail?: (w: number) => { name: string; detail: Detail }): BodyPart[] {
  const head = (d: { name: string; detail: Detail }): BodyPart => ({ kind: 'back', label: back, name: d.name, title: d.detail.title })
  if (width >= BESIDE_FROM && besideDetail) {
    const rightW = width - BESIDE_LIST - GUTTER
    const d = besideDetail(rightW)
    const left: BodyPart[] = [{ kind: 'back', label: back, name: '', title: [] }, readingsPart(r, BESIDE_LIST, 1, d.detail.id)]
    const right: BodyPart[] = [{ kind: 'lines', lines: [fitLine([{ text: '▾ ', tone: 'accent' }, { text: d.name, bold: true, tone: 'accent' }, { text: '  ' }, ...d.detail.title], rightW)] }, { kind: 'lines', lines: d.detail.lines }]
    return [{ kind: 'beside', left, right, leftWidth: BESIDE_LIST }]
  }
  return [head(open), { kind: 'lines', lines: open.detail.lines }]
}

// ------------------------------------------------------------------ the other views

/** The timeline's lines: TIME and CACHE, then the tasks, waits, agents and jobs on one axis. */
export function timelineBody(time: TimeBlocks, empty?: string): BodyPart[] {
  const lines = [...time.head, ...(time.axis ? [time.axis] : []), ...time.rows, ...(empty ? [[muted(empty)]] : [])]
  return [{ kind: 'lines', lines }]
}

/** The turns: the mission over them, the AI ETA's tally, then the last 20 turns, each with a tool call a press. */
export function turnsBody(r: Readings, width: number, ai: Line[]): BodyPart[] {
  const L = r.ctx.locale
  const c = r.c
  const history = historyRows(r, width)
  const title = c.history.length === 0 ? t(L, 'pane.history.zero') : c.history.length === 1 ? t(L, 'pane.history.one') : t(L, 'pane.history', { n: Math.min(20, c.history.length) })
  const parts: BodyPart[] = [{ kind: 'lines', lines: missionLines(r, width) }, { kind: 'blank' }]
  if (ai.length > 0) parts.push({ kind: 'lines', lines: ai }, { kind: 'blank' })
  parts.push({ kind: 'lines', lines: [[{ text: title, bold: true, tone: 'muted' }], ...(history.head ? [history.head] : [])] })
  parts.push({ kind: 'turns', rows: history.rows })
  return parts
}

/** Presses laid out left to right in rows of `width`, a column between them. */
function layOut(presses: readonly Press[], width: number): Press[][] {
  const rows: Press[][] = [[]]
  let used = 0
  for (const press of presses) {
    const row = rows.at(-1) as Press[]
    if (row.length > 0 && used + 1 + press.width > width) {
      rows.push([press])
      used = press.width
    } else {
      row.push(press)
      used += (row.length > 1 ? 1 : 0) + press.width
    }
  }
  return rows.filter(row => row.length > 0)
}

/** The band's layout: its help, each tile in the band a press that removes it, each other one a press that adds it, and reset. */
export function bandBody(L: Locale, width: number, inBand: readonly TileId[], notInBand: readonly TileId[], isDefault: boolean): BodyPart[] {
  const presses: Press[] = [
    ...inBand.map((id, i): Press => {
      const label = `${i + 1}.${id} ×`
      return { key: `pane-rm-${id}`, label, width: displayWidth(label), kind: 'remove', tile: id }
    }),
    ...notInBand.map((id): Press => ({ key: `pane-add-${id}`, label: `+ ${id}`, width: displayWidth(`+ ${id}`), kind: 'add', tile: id })),
    ...(isDefault ? [] : [{ key: 'pane-reset', label: t(L, 'pane.reset'), width: displayWidth(t(L, 'pane.reset')) + 4, kind: 'reset' as const }]),
  ]
  return [{ kind: 'lines', lines: wrapLine([muted(t(L, 'pane.bandHelp'))], width, 3) }, { kind: 'presses', rows: layOut(presses, width) }]
}

/**
 * The handover: write and copy, whether and when it was written, then its
 * text as lines: headings bold, quotes and lists set in, code as it is.
 */
export function handoverBody(L: Locale, width: number, status: Line, text: string): BodyPart[] {
  const write = t(L, 'pane.write')
  const copy = t(L, 'pane.copy')
  const presses: Press[] = [
    { key: 'pane-write', label: write, width: displayWidth(write) + 4, kind: 'write', isPrimary: true },
    { key: 'pane-copy', label: copy, width: displayWidth(copy) + 4, kind: 'copy' },
  ]
  const room = width - presses.reduce((sum, p) => sum + p.width + 1, 0)
  return [{ kind: 'presses', rows: [presses] }, { kind: 'lines', lines: [fitLine(status, Math.max(8, room > 12 ? width : width))] }, { kind: 'blank' }, { kind: 'lines', lines: markdownLines(text, width) }]
}

/** Markdown as lines `width` wide: `#` headings bold, `>` quotes and `-` items set in, ``` code as it is, backticks and underscores dropped. */
export function markdownLines(text: string, width: number): Line[] {
  const out: Line[] = []
  let isCode = false
  const clean = (s: string) => s.replace(/`([^`]*)`/g, '$1').replace(/(^|\s)_([^_]+)_(?=\s|$)/g, '$1$2')
  for (const raw of text.split('\n')) {
    if (/^(```|~~~)/.test(raw)) {
      isCode = !isCode
      continue
    }
    if (isCode) {
      out.push(fitLine([muted(`  ${raw}`)], width))
      continue
    }
    if (raw.trim() === '') {
      if (out.length > 0 && plain(out.at(-1) ?? []).trim() !== '') out.push([])
      continue
    }
    const heading = /^(#{1,6})\s+(.*)$/.exec(raw)
    if (heading) {
      out.push(fitLine([{ text: clean(heading[2] ?? ''), bold: true, ...(heading[1] === '#' ? {} : { tone: 'muted' as const }) }], width))
      continue
    }
    const quote = /^>\s?(.*)$/.exec(raw)
    if (quote) {
      for (const line of wrapLine([{ text: clean(quote[1] ?? '') }], Math.max(8, width - 2), 6)) out.push([muted('│ '), ...line])
      continue
    }
    const item = /^(\s*)- (\[[ x]\] )?(.*)$/.exec(raw)
    if (item) {
      const box = item[2]
      const mark: Span = box === '[x] ' ? { text: '✓ ', tone: 'ok' } : box === '[ ] ' ? muted('· ') : muted('• ')
      const lines = wrapLine([{ text: clean(item[3] ?? ''), ...(box === '[x] ' ? { tone: 'muted' as const } : {}) }], Math.max(8, width - 2), 4)
      lines.forEach((line, i) => out.push([i === 0 ? mark : { text: '  ' }, ...line]))
      continue
    }
    for (const line of wrapLine([{ text: clean(raw) }], width, 6)) out.push(line)
  }
  while (out.length > 0 && plain(out.at(-1) ?? []).trim() === '') out.pop()
  return out
}

/** The guide: each part's name in a column, its words wrapped beside it; a name too long for the column stands on a line of its own. */
export function guideBody(rows: readonly GuideRow[], width: number): BodyPart[] {
  const nameW = Math.max(8, Math.min(12, Math.floor(width / 5)))
  const lines: Line[] = []
  for (const row of rows) {
    const wrapped = wrapLine([{ text: row.text }], Math.max(12, width - nameW), 14)
    const isLong = displayWidth(row.name) > nameW - 1
    if (isLong) lines.push([{ text: fit(row.name, width), bold: true, tone: 'muted' }])
    wrapped.forEach((line, i) => lines.push([i === 0 && !isLong ? { text: pad(row.name, nameW), bold: true, tone: 'muted' } : { text: ' '.repeat(nameW) }, ...line]))
  }
  return [{ kind: 'lines', lines }]
}

// ------------------------------------------------------------------ the whole pane

/** The pane, ready to draw: its header, its body and the line at its foot, and the window the body scrolls in. */
export type PaneModel = {
  width: number
  view: PaneView
  bar: ViewBar
  /** The view bar's rule under it: dropped in a pane of few rows (an inline one). */
  rule: boolean
  /** Outside the overview, and in a drill-down: the progress in one line, pinned under the bar. */
  summary?: Summary
  body: BodyPart[]
  hint: Line
}

/** Rows the header takes: the bar, its rule, the summary. */
export function headRows(m: Pick<PaneModel, 'rule' | 'summary'>): number {
  return 1 + (m.rule ? 1 : 0) + (m.summary ? 1 : 0)
}

/** What a pane is built from besides the readings: its size, the view, and the open view's own parts. */
export type PaneInput = {
  width: number
  rows: number
  view: PaneView
  isFocused: boolean
  /** The open view's body, built by the caller (it alone holds the timeline's clock, the handover's text...). */
  body: (plan: OverviewPlan) => BodyPart[]
}

/** The pane's model: the bar (the full names where they fit), the summary outside the overview, the body, the hint. */
export function paneModel(r: Readings, input: PaneInput): PaneModel {
  const L = r.ctx.locale
  const { width, rows, view } = input
  const plan = overviewPlan(r, width, rows)
  const isDrilled = view.view === 'overview' && view.detail !== undefined
  const rule = view.view === 'overview' && !isDrilled ? plan.rule : rows >= RULE_FROM_ROWS
  const summary = view.view !== 'overview' || isDrilled ? summaryLine(r, width) : undefined
  const body = input.body(plan)
  const head = 1 + (rule ? 1 : 0) + (summary ? 1 : 0)
  const canScroll = sumRows(body) > Math.max(1, rows - head - 1)
  return { width, view, bar: viewBar(L, view.view, width), rule, ...(summary ? { summary } : {}), body, hint: hintLine(L, { view: view.view, isDrilled, isFocused: input.isFocused, canScroll }, width) }
}

export { barWidth }

