// The pane's pinned header, in the terminal: the view bar (and the summary)
// on top and the hint at the bottom stay where they are, and the body between
// them scrolls in a window of its own, a box that clips it moved by
// quackpit's own hooks. Claude Code 2.1.296 draws such a box (a fixed height
// with its overflow hidden, around a box moved up by a negative margin), and
// raises `ui.scroll` and `ui.focus` for it as follows, as a live probe showed:
//
//   - a tree that fits the pane's rows is never scrolled by the engine: page
//     keys still raise `ui.scroll`, by the pane's rows either way (End and
//     PageDown cannot be told apart), and the arrows move the focus;
//   - a tree one row taller than the rows makes the arrows raise `ui.scroll`
//     by one row; answered without passing it on, the engine's own window
//     stays put, the extra row out of sight;
//   - the wheel raises `ui.scroll` with the pointer's cell;
//   - Tab onto a press the box clips raises `ui.focus` with its key.
//
// So a body that overflows its window is drawn with one row more than the
// pane has, and each move goes to the body's own offset. Pure.

/** Where the body's window stands: its first row, as an offset into the body. */
export type PinState = { top: number }

/** The window's rows: the pane's rows less the header's and the footer's, one at least. */
export function windowRows(paneRows: number, headRows: number, footRows: number): number {
  return Math.max(1, paneRows - headRows - footRows)
}

/** The furthest the window can move: the body's rows past the window's. */
export function maxTop(bodyRows: number, rows: number): number {
  return Math.max(0, bodyRows - rows)
}

export function clampTop(top: number, bodyRows: number, rows: number): number {
  return Math.max(0, Math.min(maxTop(bodyRows, rows), Math.round(top)))
}

/**
 * The window after a move the engine raised: a page key's (`by` the pane's
 * own rows) moves a window's height less a row, so a line of the last page
 * stays in view; an arrow's or the wheel's moves its own rows.
 */
export function scrolled(top: number, by: number, paneRows: number, bodyRows: number, rows: number): number {
  const isPage = Math.abs(by) >= paneRows
  const step = isPage ? Math.sign(by) * Math.max(1, rows - 1) : by
  return clampTop(top + step, bodyRows, rows)
}

/**
 * The window after the focus moved onto a press at body row `at`, `height`
 * rows tall: moved the least that shows it whole, or not at all when it
 * already shows.
 */
export function followed(top: number, at: number, height: number, bodyRows: number, rows: number): number {
  if (at < top) return clampTop(at, bodyRows, rows)
  if (at + height > top + rows) return clampTop(at + height - rows, bodyRows, rows)
  return top
}

/** Whether the body overflows its window: then it is drawn a row taller than the pane, so the arrows scroll it. */
export function overflows(bodyRows: number, rows: number): boolean {
  return bodyRows > rows
}

files.src/views.ts:
// The pane's views, a view at a time under a header that stays in view: the
// overview (progress and the instruments), the timeline, the turns, the
// band's layout, the handover and the guide. A bar of presses on top, each
// with its digit as its key; outside the overview a one-line summary of the
// progress under it; at the bottom one line naming the keys of the view in
// front. Host-neutral; the adapter draws them. Pure.

import type { DetailId } from './details'
import { t, type Key, type Locale } from './i18n'
import { displayWidth, endNarrow, fit, type Line, type Span } from './text'

export const VIEW_IDS = ['overview', 'timeline', 'turns', 'band', 'handover', 'guide'] as const
export type ViewId = (typeof VIEW_IDS)[number]

export function isViewId(x: unknown): x is ViewId {
  return typeof x === 'string' && (VIEW_IDS as readonly string[]).includes(x)
}

/** Which view is in front, and in the overview the instrument drilled into: what a redraw, a reload and /clear keep. */
export type PaneView = { view: ViewId; detail?: DetailId }

export const DEFAULT_VIEW: PaneView = { view: 'overview' }

const DETAIL_IDS: readonly DetailId[] = ['pace', 'limits', 'context', 'cost', 'checks', 'files', 'agents', 'session', 'health']

export function isDetailId(x: unknown): x is DetailId {
  return typeof x === 'string' && (DETAIL_IDS as readonly string[]).includes(x)
}

/**
 * A stored view read back. An older build kept `{ tab, detail }`: a tab and a detail
 * open under the grid, which no longer go together; it opens on the overview.
 * Anything else is none.
 */
export function asView(x: unknown): PaneView | undefined {
  if (typeof x !== 'object' || x === null) return undefined
  const v = x as { view?: unknown; detail?: unknown; tab?: unknown }
  if (!isViewId(v.view)) return v.tab !== undefined ? DEFAULT_VIEW : undefined
  // A detail is the overview's alone.
  return { view: v.view, ...(v.view === 'overview' && isDetailId(v.detail) ? { detail: v.detail } : {}) }
}

/** A view's press in the bar: its digit (its key once the pane has the keyboard), its label, its width as drawn (`1: label`). */
export type ViewTab = { id: ViewId; hotkey: string; label: string; width: number }

/** The bar, as wide as it is drawn: its tabs, the gap between them, and the rule under them. */
export type ViewBar = { tabs: ViewTab[]; gap: number; rule: Line }

/**
 * A space each press carries after its label where the label ends on a wide
 * character: the focus ring then ends on a narrow one. Warp leaves the second
 * half of a wide character that ends a highlighted run unlit (`1: 타임라인`
 * lit 10 of its 11 columns), though Claude Code sends the whole run.
 */
export function tabLabel(label: string): string {
  return endNarrow(label)
}

/** How wide the bar is drawn: each tab, the gaps between. */
export function barWidth(bar: Pick<ViewBar, 'tabs' | 'gap'>): number {
  return bar.tabs.reduce((sum, tab) => sum + tab.width, 0) + bar.gap * Math.max(0, bar.tabs.length - 1)
}

/**
 * The view bar `width` columns wide: each view its digit and its name, the
 * open one bold, and under them a rule, heavy under the open view. The names
 * are the full ones where they fit with a gap of two, then one; else the
 * short ones, which fit 56 columns in every language.
 */
export function viewBar(L: Locale, open: ViewId, width: number): ViewBar {
  const forms: { short: boolean; gap: number }[] = [
    { short: false, gap: 2 },
    { short: false, gap: 1 },
    { short: true, gap: 2 },
    { short: true, gap: 1 },
  ]
  const build = (short: boolean, gap: number): ViewBar => {
    const tabs = VIEW_IDS.map((id, i): ViewTab => {
      const label = tabLabel(t(L, short ? (`view.short.${id}` as Key) : (`view.${id}` as Key)))
      const hotkey = String(i + 1)
      return { id, hotkey, label, width: hotkey.length + 2 + displayWidth(label) }
    })
    return { tabs, gap, rule: [] }
  }
  const chosen = forms.map(f => build(f.short, f.gap)).find(bar => barWidth(bar) <= width) ?? build(true, 1)
  const at = chosen.tabs.findIndex(tab => tab.id === open)
  const from = chosen.tabs.slice(0, at).reduce((x, tab) => x + tab.width + chosen.gap, 0)
  const under = chosen.tabs[at]?.width ?? 0
  const w = Math.max(from + under, width)
  const rule: Line = [{ text: '─'.repeat(from), tone: 'muted' }, { text: '━'.repeat(under), tone: 'accent' }, { text: '─'.repeat(Math.max(0, w - from - under)), tone: 'muted' }]
  return { ...chosen, rule }
}

/** What the hint at the bottom names: the view in front, whether a detail is open, whether the pane has the keyboard. */
export type HintState = { view: ViewId; isDrilled: boolean; isFocused: boolean; canScroll: boolean }

/**
 * The line at the bottom: the keys of the view in front, its most useful
 * first, as many as fit. Until a click gives the pane the keyboard, it says
 * so first: no key reaches the pane before.
 */
export function hintLine(L: Locale, s: HintState, width: number): Line {
  const parts: Key[] = []
  if (!s.isFocused) parts.push('hint.click')
  if (s.isDrilled) parts.push('hint.back')
  if (s.view === 'overview' && !s.isDrilled) parts.push('hint.gauge')
  if (s.view === 'turns') parts.push('hint.turn')
  if (s.view === 'band') parts.push('hint.tile')
  if (s.view === 'handover') parts.push('hint.write')
  if (s.canScroll) parts.push('hint.scroll')
  parts.push('hint.views')
  if (s.isFocused) parts.push('hint.esc')
  const said = parts.map(key => t(L, key))
  const kept: string[] = []
  for (const text of said) {
    const next = [...kept, text].join(' · ')
    if (displayWidth(next) <= width) kept.push(text)
    else if (kept.length === 0) {
      kept.push(fit(text, width))
      break
    }
  }
  const span: Span = { text: kept.join(' · '), tone: 'muted' }
  return [span]
}

files.src/prefs.ts:
// Settings and the band's layout. userConfig holds the defaults; the
// `/quackpit add|remove|move|rows|duck` commands write an override to the
// store that every session uses until the matching userConfig value itself
// changes (the override remembers which values it replaced). Pure: the
// adapter reads and writes the store.

import { resolveLocale, type Locale } from './i18n'
import { DEFAULT_TILES, isTileId, parseTiles, type TileId } from './tiles'

export type Graphics = 'auto' | 'pixels' | 'text'

export type Settings = {
  tiles: TileId[]
  /** userConfig's tiles as written, so an override knows what it replaced. */
  tilesText: string
  rows: number
  duck: boolean
  sound: boolean
  graphics: Graphics
  locale: Locale
  /** The opt-in AI ETA: off unless the person turned it on. */
  aiEta: boolean
}

export const MIN_ROWS = 1
export const MAX_ROWS = 4

export function clampRows(n: unknown, fallback = 2): number {
  const v = typeof n === 'number' ? n : typeof n === 'string' ? Number(n) : NaN
  if (!Number.isFinite(v)) return fallback
  return Math.max(MIN_ROWS, Math.min(MAX_ROWS, Math.round(v)))
}

/** userConfig as `register` receives it; anything missing or malformed gets its default. */
export function readSettings(options: Readonly<Record<string, unknown>>, systemLocale?: string): Settings {
  const tilesText = typeof options.tiles === 'string' ? options.tiles : DEFAULT_TILES.join(',')
  const parsed = parseTiles(tilesText)
  const graphics = options.graphics === 'pixels' || options.graphics === 'text' ? options.graphics : 'auto'
  return {
    tiles: parsed.length > 0 ? parsed : [...DEFAULT_TILES],
    tilesText,
    rows: clampRows(options.rows),
    duck: options.duck !== false,
    sound: options.sound === true,
    graphics,
    locale: resolveLocale(options.locale, systemLocale),
    aiEta: options.aiEta === true,
  }
}

/** The userConfig values an override was made against. */
export type Base = { tiles: string; rows: number; duck: boolean }

export type LayoutRecord = {
  v: 1
  tiles?: TileId[]
  rows?: number
  duck?: boolean
  base: Base
  /** Where the override came from: your commands, or claude-hud's config on first run. */
  source: 'command' | 'claude-hud'
}

export function baseOf(s: Settings): Base {
  return { tiles: s.tilesText, rows: s.rows, duck: s.duck }
}

export function asLayout(x: unknown): LayoutRecord | undefined {
  if (typeof x !== 'object' || x === null) return undefined
  const r = x as Record<string, unknown>
  const base = r.base as Record<string, unknown> | undefined
  if (r.v !== 1 || !base || typeof base.tiles !== 'string' || typeof base.rows !== 'number' || typeof base.duck !== 'boolean') return undefined
  const out: LayoutRecord = {
    v: 1,
    base: { tiles: base.tiles, rows: base.rows, duck: base.duck },
    source: r.source === 'claude-hud' ? 'claude-hud' : 'command',
  }
  if (Array.isArray(r.tiles)) out.tiles = r.tiles.filter(isTileId).filter((id, i, all) => all.indexOf(id) === i)
  if (typeof r.rows === 'number') out.rows = clampRows(r.rows)
  if (typeof r.duck === 'boolean') out.duck = r.duck
  return out
}

export type Layout = { tiles: TileId[]; rows: number; duck: boolean; source?: LayoutRecord['source'] }

/** Whether two layouts draw the same band: the same tiles in the same order, rows and duck. */
export function isSameLayout(a: Layout, b: Layout): boolean {
  return a.rows === b.rows && a.duck === b.duck && a.tiles.length === b.tiles.length && a.tiles.every((id, i) => b.tiles[i] === id)
}

/** Whether an override still stands: userConfig has not changed since it was made. */
export function isCurrent(record: LayoutRecord | undefined, s: Settings): record is LayoutRecord {
  if (!record) return false
  const b = baseOf(s)
  return record.base.tiles === b.tiles && record.base.rows === b.rows && record.base.duck === b.duck
}

export function effectiveLayout(s: Settings, record: LayoutRecord | undefined): Layout {
  if (!isCurrent(record, s)) return { tiles: [...s.tiles], rows: s.rows, duck: s.duck }
  return {
    tiles: record.tiles ?? [...s.tiles],
    rows: record.rows ?? s.rows,
    duck: record.duck ?? s.duck,
    source: record.source,
  }
}

function withChange(s: Settings, record: LayoutRecord | undefined, change: Partial<Pick<LayoutRecord, 'tiles' | 'rows' | 'duck'>>): LayoutRecord {
  const current = isCurrent(record, s) ? record : undefined
  return { v: 1, ...(current ?? {}), ...change, base: baseOf(s), source: 'command' }
}

export type Change = { record: LayoutRecord; outcome: 'done' } | { record: LayoutRecord | undefined; outcome: 'already' | 'missing' | 'unknown' | 'bad' }

export function addTile(s: Settings, record: LayoutRecord | undefined, name: string, at?: number): Change {
  const id = name.toLowerCase()
  if (!isTileId(id)) return { record, outcome: 'unknown' }
  const tiles = effectiveLayout(s, record).tiles
  if (tiles.includes(id)) return { record, outcome: 'already' }
  const next = [...tiles]
  next.splice(at === undefined ? next.length : Math.max(0, Math.min(next.length, at - 1)), 0, id)
  return { record: withChange(s, record, { tiles: next }), outcome: 'done' }
}

export function removeTile(s: Settings, record: LayoutRecord | undefined, name: string): Change {
  const id = name.toLowerCase()
  if (!isTileId(id)) return { record, outcome: 'unknown' }
  const tiles = effectiveLayout(s, record).tiles
  if (!tiles.includes(id)) return { record, outcome: 'missing' }
  return { record: withChange(s, record, { tiles: tiles.filter(t => t !== id) }), outcome: 'done' }
}

/** Moves a tile to position `n` (1 is leftmost); one not in the band is added there. */
export function moveTile(s: Settings, record: LayoutRecord | undefined, name: string, n: number | undefined): Change {
  const id = name.toLowerCase()
  if (!isTileId(id)) return { record, outcome: 'unknown' }
  if (n === undefined || !Number.isFinite(n) || n < 1) return { record, outcome: 'bad' }
  const tiles = effectiveLayout(s, record).tiles.filter(t => t !== id)
  tiles.splice(Math.min(tiles.length, Math.round(n) - 1), 0, id)
  return { record: withChange(s, record, { tiles }), outcome: 'done' }
}

export function setRows(s: Settings, record: LayoutRecord | undefined, n: number | undefined): Change {
  if (n === undefined || !Number.isInteger(n) || n < MIN_ROWS || n > MAX_ROWS) return { record, outcome: 'bad' }
  return { record: withChange(s, record, { rows: n }), outcome: 'done' }
}

export function setDuck(s: Settings, record: LayoutRecord | undefined, on: boolean): Change {
  return { record: withChange(s, record, { duck: on }), outcome: 'done' }
}

/** The record claude-hud's config maps to on first run. */
export function hudLayout(s: Settings, tiles: readonly TileId[]): LayoutRecord {
  return { v: 1, tiles: [...tiles], base: baseOf(s), source: 'claude-hud' }
}

files.src/progress.ts:
// The current task list, rebuilt from Claude's own todo and task tool calls
// as `tool.call` saw them: TodoWrite replaces the whole list, TaskCreate adds
// an item, TaskUpdate changes or deletes one, TaskList re-reads them all.
// Each item keeps when it was first seen running and first seen done, from
// the calls' own times, so the list can say how long is left at its own pace.
// Pure; the adapter hands each finished call in as plain data.

import { clip } from './format'
import { maskSecrets } from './mask'
import { median, MINUTE } from './metrics'

export type TaskStatus = 'pending' | 'in_progress' | 'completed'

export type Task = {
  id: string
  title: string
  /** What the spinner says while it runs ("Writing tests"). */
  active?: string
  status: TaskStatus
  /** When a call first showed it in progress. */
  startedAt?: number
  /** When a call first showed it completed; gone again if it reopens. */
  doneAt?: number
  /** How long it waited on the person while it ran, which its length leaves out; set as it finishes. */
  heldMs?: number
}

export type TaskList = {
  source: 'todo' | 'task'
  items: Task[]
  /** The turn number that last changed it. */
  turn: number
  updatedAt: number
}

const MAX_TASKS = 100
const MAX_TITLE = 200

/** A title or spinner text as kept: masked, then cut. */
const kept = (text: string): string => clip(maskSecrets(text), MAX_TITLE)

const STATUSES: readonly TaskStatus[] = ['pending', 'in_progress', 'completed']

function asStatus(x: unknown): TaskStatus | undefined {
  return typeof x === 'string' && (STATUSES as readonly string[]).includes(x) ? (x as TaskStatus) : undefined
}

function str(x: unknown): string | undefined {
  return typeof x === 'string' && x.trim() !== '' ? x : undefined
}

function obj(x: unknown): Record<string, unknown> | undefined {
  return typeof x === 'object' && x !== null && !Array.isArray(x) ? (x as Record<string, unknown>) : undefined
}

/** An item as a call at `at` shows it, its times carried over from what it was before. */
function timed(item: Task, before: Task | undefined, at: number): Task {
  const { startedAt: _s, doneAt: _d, heldMs: _h, ...rest } = item
  const startedAt = before?.startedAt ?? (item.status === 'in_progress' ? at : undefined)
  const doneAt = item.status !== 'completed' ? undefined : before?.status === 'completed' ? before.doneAt : at
  // A task still done keeps the time it waited; one that reopens measures it again when it finishes.
  const heldMs = doneAt !== undefined && before?.status === 'completed' ? before.heldMs : undefined
  return { ...rest, ...(startedAt !== undefined ? { startedAt } : {}), ...(doneAt !== undefined ? { doneAt } : {}), ...(heldMs !== undefined ? { heldMs } : {}) }
}

/** A finished todo or task tool call, as the adapter hands it over. */
export type TaskCall = {
  tool: string
  input: Record<string, unknown>
  /** The tool's record (`result` from `next(e)`), when it answered without error. */
  result?: unknown
  isError: boolean
}

export const TASK_TOOLS: ReadonlySet<string> = new Set(['TodoWrite', 'TaskCreate', 'TaskUpdate', 'TaskList'])

/** The list after one call; the same list when the call changes nothing. */
export function applyTaskCall(list: TaskList | undefined, call: TaskCall, turn: number, at: number): TaskList | undefined {
  if (call.isError || !TASK_TOOLS.has(call.tool)) return list
  switch (call.tool) {
    case 'TodoWrite': {
      const todos = Array.isArray(call.input.todos) ? call.input.todos : undefined
      if (!todos) return list
      // A rewrite of the list: each item finds what it was by its words, its times kept.
      const was = new Map<string, Task[]>()
      for (const item of list?.source === 'todo' ? list.items : []) was.set(item.title, [...(was.get(item.title) ?? []), item])
      const items: Task[] = []
      todos.slice(0, MAX_TASKS).forEach((raw, i) => {
        const t = obj(raw)
        const title = str(t?.content)
        const status = asStatus(t?.status)
        if (!title || !status) return
        const active = str(t?.activeForm)
        const item: Task = { id: `todo-${i}`, title: kept(title), status, ...(active ? { active: kept(active) } : {}) }
        items.push(timed(item, was.get(item.title)?.shift(), at))
      })
      return { source: 'todo', items, turn, updatedAt: at }
    }
    case 'TaskCreate': {
      const task = obj(obj(call.result)?.task)
      const id = str(task?.id)
      const title = str(call.input.subject) ?? str(task?.subject)
      if (!id || !title) return list
      const active = str(call.input.activeForm)
      const base = list?.source === 'task' ? list.items : []
      const created: Task = { id, title: kept(title), status: 'pending', ...(active ? { active: kept(active) } : {}) }
      const items = [...base.filter(item => item.id !== id), created]
      return { source: 'task', items: items.slice(-MAX_TASKS), turn, updatedAt: at }
    }
    case 'TaskUpdate': {
      const result = obj(call.result)
      if (result?.success === false) return list
      const id = str(call.input.taskId) ?? str(result?.taskId)
      if (!id) return list
      const status = call.input.status
      const base = list?.source === 'task' ? list.items : []
      if (status === 'deleted') {
        if (!base.some(item => item.id === id)) return list
        return { source: 'task', items: base.filter(item => item.id !== id), turn, updatedAt: at }
      }
      const known = base.find(item => item.id === id)
      const subject = str(call.input.subject)
      const active = str(call.input.activeForm)
      const next = timed(
        {
          id,
          title: kept(subject ?? known?.title ?? `#${id}`),
          status: asStatus(status) ?? known?.status ?? 'pending',
          ...(active ? { active: kept(active) } : known?.active ? { active: known.active } : {}),
        },
        known,
        at,
      )
      const items = known ? base.map(item => (item.id === id ? next : item)) : [...base, next]
      return { source: 'task', items: items.slice(-MAX_TASKS), turn, updatedAt: at }
    }
    case 'TaskList': {
      const tasks = obj(call.result)?.tasks
      if (!Array.isArray(tasks)) return list
      const before = new Map((list?.source === 'task' ? list.items : []).map(item => [item.id, item]))
      const items: Task[] = []
      for (const raw of tasks.slice(0, MAX_TASKS)) {
        const t = obj(raw)
        const id = str(t?.id)
        const title = str(t?.subject)
        const status = asStatus(t?.status)
        if (!id || !title || !status) continue
        const active = before.get(id)?.active
        items.push(timed({ id, title: kept(title), status, ...(active ? { active } : {}) }, before.get(id), at))
      }
      return { source: 'task', items, turn, updatedAt: at }
    }
  }
  return list
}

export type Progress = {
  done: number
  total: number
  /** The item in progress, else the next pending one. */
  current?: Task
  isCurrentRunning: boolean
  isComplete: boolean
}

export function progressOf(list: TaskList | undefined): Progress | undefined {
  if (!list || list.items.length === 0) return undefined
  const done = list.items.filter(item => item.status === 'completed').length
  const running = list.items.find(item => item.status === 'in_progress')
  const pending = list.items.find(item => item.status === 'pending')
  const current = running ?? pending
  return {
    done,
    total: list.items.length,
    ...(current ? { current } : {}),
    isCurrentRunning: running !== undefined,
    isComplete: done === list.items.length,
  }
}

/**
 * Whether the list is still worth showing: an open list always is; a
 * finished one until a later turn starts.
 */
export function isListLive(list: TaskList | undefined, turnNumber: number): boolean {
  const p = progressOf(list)
  if (!list || !p) return false
  return !p.isComplete || turnNumber <= list.turn
}

/** Completed tasks with a known length needed before the list says how long is left. */
export const MIN_DONE_FOR_ESTIMATE = 2
/** Past this the estimate would be no help: it is not shown. */
const MAX_ESTIMATE_MS = 12 * 60 * MINUTE

/**
 * How long the open tasks will take at this list's own pace: the median
 * length of its completed tasks (each from first seen running to first seen
 * done), times the tasks still open, less what the running one has had.
 * Undefined until 2 tasks have a known length, and wherever the result would
 * be nonsense: nothing open, already overrun, or over 12 hours.
 */
export function timeLeft(list: TaskList | undefined, now: number): number | undefined {
  if (!list) return undefined
  const lengths: number[] = []
  for (const t of list.items) {
    if (t.status === 'completed' && t.startedAt !== undefined && t.doneAt !== undefined && t.doneAt >= t.startedAt) lengths.push(t.doneAt - t.startedAt)
  }
  if (lengths.length < MIN_DONE_FOR_ESTIMATE) return undefined
  const typical = median(lengths)
  const open = list.items.filter(t => t.status !== 'completed').length
  if (typical === undefined || typical <= 0 || open === 0) return undefined
  const running = list.items.find(t => t.status === 'in_progress')
  const spent = running?.startedAt !== undefined ? Math.max(0, now - running.startedAt) : 0
  const left = typical * open - spent
  return left > 0 && left <= MAX_ESTIMATE_MS ? left : undefined
}

